(window.GIM_TS=window.GIM_TS||{})["Sotah.1"]={"from":24,"a":[["\u0003גסטרא\u0004 (חיל המבצר) \u0003של בית פעור,\u0004 ואמרו להם: \u0003הראנו היכן משה קבור. עמדו\u0004 אנשים \u0003למעלה\u0004 על ההר — \u0003נדמה להם\u0004 שהקבר \u0003למטה,\u0004 עמדו \u0003למטה —\u0004 \u0003נדמה להם למעלה. נחלקו לשתי כיתות\u0004 (קבוצות), \u0003אותן שעומדים למעלה —\u0004 \u0003נדמה להן\u0004 שהוא \u0003למטה,\u0004 אלה שעומדים \u0003למטה —\u0004 \u0003נדמה להן\u0004 שהוא \u0003למעלה, לקיים מה שנאמר \"ולא ידע איש את קברתו\"\u0004 (דברים לד, ו).","\u0003ר' חמא בר' חנינא אמר: אף משה רבינו\u0004 עצמו \u0003אינו יודע היכן\u0004 הוא \u0003קבור; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ולא ידע איש את קברתו\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"וזאת הברכה אשר ברך משה איש האלהים\"\u0004 (דברים לג, א), כלומר, אפילו משה הנקרא \"איש האלקים\" לא ידע. \u0003ואמר ר' חמא בר' חנינא: מפני מה נקבר משה אצל בית פעור —\u0004 \u0003כדי לכפר\u0004 בכך \u0003על מעשה פעור.\u0004 \u0003ואמר ר' חמא בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אחרי ה' אלהיכם תלכו\"\u0004 (דברים יג, ה), \u0003וכי אפשר לו לאדם להלך אחר שכינה? והלא כבר נאמר \"כי ה' אלהיך אש אכלה הוא\"\u0004 (דברים ד, כד)!","","\u0003אלא\u0004 הכוונה היא שיש \u0003להלך אחר מדותיו של הקדוש ברוך הוא\u0004 ולנהוג כמו כן; \u0003מה הוא מלביש ערומים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעש ה' אלהים לאדם ולאשתו כתנות עור וילבשם\"\u0004 (בראשית ג, כא) — \u0003אף אתה הלבש ערומים. הקדוש ברוך הוא ביקר חולים, דכתיב\u0004 \u0005[שנאמר]:\u0006 לאחר שמל אברהם את עצמו והיה חולה מכאב המילה \u0003\"וירא אליו ה' באלני ממרא\"\u0004 (בראשית יח, א) — \u0003אף אתה בקר חולים. הקדוש ברוך הוא ניחם אבלים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי אחרי מות אברהם ויברך אלהים את יצחק בנו\"\u0004 (בראשית כה, יא) — \u0003אף אתה נחם אבלים. הקדוש ברוך הוא קבר מתים, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויקבר אתו בגי\"\u0004 (דברים לד, ו) — \u0003אף אתה קבר מתים.\u0004 \u0003כיון שהזכרנו כתוב זה על\u0004 \u0003כתנות עור\u0004 דנים בו; \u0003רב ושמואל\u0004 נחלקו בפירושו, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 כתנות אלה היו עשויות מ\u0003דבר הבא מן העור, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: דבר שהעור נהנה ממנו.\u0004","","\u0003דרש ר' שמלאי: תורה תחלתה גמילות חסדים וסופה גמילות חסדים.\u0004 כיצד? \u0003תחילתה גמילות חסדים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעש ה' אלהים לאדם ולאשתו כתנות עור וילבשם\"\u0004 (בראשית ג, כא), הרי גמילות חסדים של הלבשת ערומים, \u0003וסופה גמילות חסדים —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויקבר אתו בגי\"\u0004 (דברים לד, ו), הרי גמילות חסדים של קבורת מתים. \u0003דרש ר' שמלאי: מפני מה נתאוה משה רבינו\u0004 כל כך \u0003ליכנס לארץ ישראל? וכי לאכול מפריה הוא צריך, או לשבוע מטובה הוא צריך? אלא כך אמר משה: הרבה מצות נצטוו ישראל ואין מתקיימין אלא בארץ ישראל, אכנס אני לארץ כדי שיתקיימו כולן על ידי.\u0004 \u0003אמר לו הקדוש ברוך הוא: כלום אתה מבקש\u0004 לעשות מצוות אלה \u0003אלא לקבל שכר —\u0004 \u0003מעלה\u0004 (מחשיב) \u0003אני עליך כאילו עשיתם\u0004 ותקבל שכרך, \u0003שנאמר:\u0004 \u0003\"לכן אחלק לו ברבים ואת עצומים יחלק שלל תחת אשר הערה למות נפשו ואת פשעים נמנה, והוא חטא רבים נשא ולפשעים יפגיע\"\u0004 (ישעיה נג, יב), וכך דורשים את הפסוק:","","\u0003\"לכן אחלק לו ברבים\",\u0004 כלומר, יקבל שכר. \u0003יכול\u0004 יקבל שכר \u0003כאחרונים ולא כראשונים —\u0004 \u0003תלמוד לומר: \"ואת עצומים יחלק שלל\", כאברהם יצחק ויעקב שהן עצומים בתורה ובמצות. \"תחת אשר הערה למות נפשו\" —\u0004 \u0003שמסר עצמו למיתה\u0004 על ישראל, \u0003שנאמר:\u0004 \u0003\"ואם אין מחני נא\u0004 מספרך אשר כתבת \u0003\"\u0004\u0003(שמות לב, לב).\u0004 \u0003\"ואת פשעים נמנה\" —\u0004 \u0003שנמנה עם מתי מדבר,\u0004 שהרי אף הוא כמותם לא נכנס לארץ. \u0003\"והוא חטא רבים נשא\" —\u0004 \u0003שכיפר על מעשה העגל. \"ולפשעים יפגיע\" —\u0004 \u0003שביקש רחמים על פושעי ישראל שיחזרו בתשובה. ואין \"פגיעה\" אלא\u0004 לשון \u0003תפלה, שנאמר:\u0004 \u0003\"ואתה אל תתפלל בעד העם הזה ואל תשא בעדם רנה ותפלה ואל תפגע בי\"\u0004 (ירמיה ז, טז).","","","","\u0003היה\u0004 בעלה \u0003מביא את מנחתה\u0004 של אשתו הסוטה לכהן \u0003בתוך כפיפה מצרית\u0004 (סל העשוי מעלי דקל) \u0003ונותנה\u0004 (את המנחה) \u0003על ידיה\u0004 של הסוטה \u0003כדי ליגעה,\u0004 שמא מתוך כך תודה לפני שתשתה.","\u0003כל המנחות תחילתן\u0004 משעת ההקדשה \u0003ו\u0004עד \u0003סופן\u0004 מונחות \u0003בכלי שרת, וזו תחילתה\u0004 מונחת \u0003בכפיפה מצרית, וסופה,\u0004 קודם ההקטרה, היתה מונחת \u0003בכלי שרת.\u0004","והבדלים נוספים: \u0003כל המנחות טעונות שמן ולבונה, וזו אינה טעונה לא שמן ולא לבונה.\u0004 וכן, \u0003כל המנחות באות מן החיטין, וזו באה מן השעורין.\u0004 ו\u0003מנחת העומר, אף על פי שבאה מן השעורין, היא היתה באה גרש\u0004 מן המובחר, כעין סולת של שעורים, \u0003וזו\u0004 של מנחת סוטה \u0003באה קמח\u0004 שאינו מנופה. \u0003רבן גמליאל אומר:\u0004 רמז הוא, \u0003כשם שמעשיה\u0004 בזנות \u0003מעשה בהמה, כך קרבנה מאכל בהמה\u0004 שהוא שעורים.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אבא חנין אומר משום\u0004 (בשם) \u0003ר' אליעזר: וכל כך למה\u0004 עושים לה — \u0003כדי ליגעה, כדי שתחזור בה\u0004 ותודה ולא תמות. ומעתה נאמר: \u0003אם ככה חסה תורה על עוברי רצונו,\u0004 על סוטה זו שעברה על רצון המקום, שנסתרה עם אחר, ועושים בה מעשים אלה כדי שתודה ולא תשתה ותמות, \u0003קל וחומר\u0004 שחסה \u0003על עושי רצונו.\u0004","ושואלים: \u0003וממאי\u0004 \u0005[ומניין]\u0006 יודע אתה שהטעם \u0003משום\u0004 ש\u0003חסה\u0004 עליה התורה \u0003הוא\u0004 הטעם לדין זה? \u0003דילמא\u0004 \u0005[שמא]\u0006 מייגעים אותה שתודה \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תימחק המגילה\u0004 ושם ה' שבתוכה! ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 תנא זה"],["\u0003משקה\u0004 את האשה במים המאררים, \u0003ואחר כך מקריב את מנחתה. דאי\u0004 \u0005[שאם]\u0006 הטעם הוא \u0003משום\u0004 מחיקת ה\u0003מגילה —\u0004 \u0003הא אימחיקא\u0004 \u0005[הרי נמחקה]\u0006 \u0003לה\u0004 כבר, ולא היו המים בודקים אותה אלא לאחר שקרבה מנחתה, ובוודאי אין זה אלא משום שחסה עליה התורה.","שנינו במשנה: \u0003כל המנחות\u0004 תחילתן וסופן בכלי שרת. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בתוספתא: \u0003סדר מנחות כיצד? אדם מביא מנחה מתוך ביתו בקלתות\u0004 (סלים) \u0003של כסף ושל זהב, ו\u0004כשמגיע לבית המקדש \u0003נותנה לתוך כלי שרת, ומקדשה בכלי שרת, ונותן עליה שמנה ולבונתה, ומוליכה אצל כהן. וכהן מוליכה אצל מזבח, ומגישה בקרן דרומית מערבית כנגד חודה של קרן, ודיו\u0004 בכך.","\u0003ומסלק את הלבונה לצד אחד, וקומץ ממקום שנתרבה שמנה\u0004 (שיש בו יותר שמן) \u0003ונותנו\u0004 את הקומץ \u0003לתוך כלי שרת, ומקדשו\u0004 את הקומץ \u0003בכלי שרת. ומלקט את לבונתה ונותנה על גביו\u0004 של הקומץ, \u0003ומעלה אותו לגבי מזבח, ומעלהו\u0004 את הקומץ \u0003ומקטירו בכלי שרת, ומולחו, ונותנו על גבי האישים\u0004 (האש).","אחרי ש\u0003קרב הקומץ שיריה\u0004 (כל שאר המנחה) \u0003נאכלין, ו\u0004אז \u0003רשאין הכהנים ליתן לתוכה\u0004 של שארית המנחה \u0003יין ושמן ודבש\u0004 (למרות שאסור להקריב דבש על גבי המזבח), \u0003ואין אסורין אלא מלחמץ\u0004 את המנחה.","\u0003קתני מיהא\u0004 \u0005[שנה\u0006 התנא \u0005על כל פנים]\u0006 שמניחים את המנחה בתחילה \u0003בקלתות של כסף ובקלתות של זהב\u0004 שהביא מביתו, ולא בכלי שרת שהוקדשו לשם כך! \u0003אמר רב פפא: אימא\u0004 \u0005[אמור]\u0006 במשנתנו שאת שאר המנחות מניחים \u0003בכלים\u0004 של מתכות יקרות \u0003הראויין לכלי שרת\u0004 אם היה מקדישם.","ומעירים: \u0003מכלל\u0004 פירוש זה למשנה אתה למד ש\u0003כפיפה מצרית לא חזיא\u0004 \u0005[ראויה]\u0006 לכלי שרת אפילו אם יקדש אותה, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי] —\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יוסי בר' יהודה, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלי שרת שעשאן של עץ, רבי פוסל ור' יוסי בר' יהודה מכשיר.\u0004","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003ר' יוסי בר' יהודה, אימר\u0004 \u0005[אמור]\u0006 ש\u0003אמר ר' יוסי בר' יהודה\u0004 להתיר \u0003ב\u0004כלי עץ \u0003חשובין,\u0004 אבל \u0003בפחותין\u0004 כגון כפיפה מצרית \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר?\u0004 וכי \u0003לית ליה\u0004 \u0005[אין\u0006 נראה \u0005לו]\u0006 \u0003לר' יוסי בר' יהודה\u0004 מה שנאמר \u0003\"הקריבהו נא לפחתך\u0004 הירצך או הישא פניך\u0003\"\u0004 (מלאכי א, ח)?! שדבר שאין נותנים אותו כמתנה לשליט (\"פחתך\") — ודאי אין מביאים אותו למקדש.","שנינו שם: \u0003ונותנה לכלי שרת, ומקדשה בכלי שרת.\u0004 ושואלים: \u0003שמעת מינה\u0004 \u0005[\u0006האם \u0005שומע אתה מכאן]\u0006 מן הציווי הכפול — לתת בכלי שרת ולקדש בו — ש\u0003כלי שרת אין מקדשין אלא מדעת,\u0004 שצריך להניח המנחה בכלי שרת על דעת ובכוונה לקדשה, ולא די בעצם נתינתה בכלי שרת? ודוחים: \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003נותנה בכלי שרת\u0004 כדי \u0003לקדשה בכלי שרת\u0004 ואינו צריך לכוון לכך.","עוד שנינו שם: \u0003ונותן עליה\u0004 בעל המנחה \u0003שמנה ולבונתה —\u0004 \u0003שנאמר: \"ויצק עליה שמן ונתן עליה לבנה\"\u0004 (ויקרא ב, א).","\u0003ומוליכה אצל כהן —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והביאה אל בני אהרן\u0004 הכהנים\u0003\"\u0004(ויקרא ב, ב).","\u0003וכהן מוליכה אצל מזבח —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והגישה אצל המזבח\"\u0004 (ויקרא ב, ח).","\u0003מגישה בקרן דרומית מערבית כנגד\u0004 \u0003חודה של קרן ודיו. מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה —","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וזאת תורת המנחה הקרב אתה בני אהרן לפני ה' אל פני המזבח\"\u0004 (ויקרא ו, ז), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר \u0003\"לפני ה'\", יכול במערב\u0004 המזבח שהוא לפני ה', שהרי קודש הקדשים הוא בצד מערב — \u0003תלמוד לומר: \"אל פני המזבח\"\u0004 הוא חזית המזבח, שהיא בדרומו, שמשם עולים להקריב על גביו. \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"אל פני המזבח\", יכול בדרום —\u0004 \u0003תלמוד לומר: \"לפני ה'\"\u0004 שמשמעו כלפי מערב. \u0003הא כיצד\u0004 נקיים את שני הכתובים כאחד — \u0003מגישה\u0004 הכהן \u0003בקרן דרומית מערבית\u0004 של מזבח \u0003כנגד חודה של קרן, ודיו.\u0004","\u0003ר' אלעזר אומר\u0004 פירוש אחר לפסוק: \u0003יכול יגישנה במערבה של קרן או לדרומה של קרן —\u0004 \u0003אמרת\u0004 (אומר אתה): \u0003כל מקום שאתה מוצא שני מקראות, אחד מקיים עצמו ומקיים דברי חבירו, ואחד מקיים עצמו ומבטל דברי חבירו —\u0004 \u0003מניחין את\u0004 המקרא \u0003שמקיים עצמו ומבטל חבירו, ותופסין את שמקיים עצמו ומקיים חבירו.\u0004 ומסבירים: \u0003כשאתה אומר \"לפני ה'\"\u0004 ועושה זאת \u0003במערב —\u0004 \u0003בטלתה \"אל פני המזבח\"\u0004 שהוא \u0003בדרום, וכשאתה אומר \"אל פני המזבח\" בדרום —\u0004 \u0003קיימתה\u0004 גם \u0003\"לפני ה'\" במערב. הא כיצד\u0004 מקיים את שניהם? \u0003מגישה לדרומה של קרן.\u0004","ושואלים: \u0003והיכן קיימתה\u0004 את \"לפני ה'\"? \u0003אמר רב אשי: קסבר האי תנא\u0004 \u0005[סבור תנא זה]\u0006 \u0003כוליה\u0004 \u0005[כל]\u0006 ה\u0003מזבח בצפון\u0004 בחציה הצפוני של העזרה \u0003קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 ולפיכך כל מקום בדרומו של המזבח הרי הוא מכוון כנגד פתח ההיכל ומול קודש הקדשים ונקרא \"לפני ה'\".","ועוד שואלים על לשון הברייתא: \u0003מאי\u0004 \u0005[מה\u0006 נוסף\u0005]\u0006 במלה \u0003\"ודיו\"? אמר רב אשי: איצטריך\u0004 \u0005[צריך]\u0006 הדבר להאמר, \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003תיבעי\u0004 \u0005[תידרש]\u0006 \u0003הגשת\u0004 ה\u0003מנחה גופה\u0004 \u0005[עצמה]\u0006 לקרן המזבח בלא חציצה של כלי, \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר כן.","ושואלים: \u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך\u0006 הוא \u0005גם כן]?\u0006 ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"והקריבה אל הכהן והגישה אל המזבח\"\u0004 (ויקרא ב, ח) \u0003מה הקרבה אצל כהן בכלי —\u0004 \u0003אף הגשה אצל מזבח בכלי,\u0004 ולא המנחה כשלעצמה.","עוד שנינו: \u0003ומסלק את לבונתה לצד אחד.\u0004 ומסבירים: \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תקמוץ\u0004 \u0005[תקמץ]\u0006 הלבונה \u0003בהדי\u0004 \u0005[ביחד עם]\u0006 ה\u0003מנחה, כדתנן\u0004 \u0005[כפי ששנינו\u0006 במשנה\u0005]:\u0006 \u0003קמץ ועלה בידו צרור\u0004 אבן, \u0003או גרגר מלח, או קורט\u0004 (פירור) \u0003לבונה —\u0004 \u0003פסול,\u0004 שצריך הקומץ להיות כולו סולת.","עוד שנינו: \u0003וקומץ ממקום שנתרבה שמנה.\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דבר זה? ומשיבים: \u0003דכתיב [שנאמר]: \"\u0004וקמץ משם מלא קומצו \u0003מסלתה ומשמנה\"\u0004 (ויקרא ב, ב) \u0003\"מגרשה ומשמנה\"\u0004 (ויקרא ב, טז) — מחלק המנחה שיש בו הרבה שמן.","עוד שנינו: \u0003ונותנו לתוך כלי שרת ומקדשו בכלי שרת.\u0004 ושואלים: \u0003למה לי? הא קדשה חדא זימנא\u0004 \u0005[הרי קידש\u0006 כבר \u0005אותו פעם אחת]\u0006 כשהביא את המנחה לעזרה! ומשיבים: \u0003מידי דהוה אדם\u0004 \u0005[כמו שהוא ב\u0006דין של \u0005דם\u0006 הקרבנות\u0005];\u0006 \u0003דם, אף על גב דקדישתיה\u0004 \u0005[אף על פי שקידשה אותו]\u0006 \u0003סכין בצואר בהמה\u0004 במגעה, שהרי הסכין כלי שרת היא, מכל מקום \u0003הדר מקדיש ליה\u0004 \u0005[חוזר ומקדש אותו]\u0006 \u0003בכלי שרת\u0004 בזמן קבלת הדם, \u0003הכא נמי לא שנא\u0004 \u0005[כאן גם כן אינו שונה]\u0006 שצריך קידוש כפול.","ומה ששנינו עוד: \u0003ומלקט את לבונתה ונותנה על גביו —\u0004 מקור הדבר הוא במה \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \"והרים... \u0003ואת כל הלבנה אשר על המנחה\u0004 והקטיר המזבח\" (ויקרא ו, ח).","עוד שנינו: \u0003ומעלהו\u0004"],["\u0003ומקטירו בכלי שרת.\u0004 ותוהים: \u0003בכלי שרת מקטיר ליה\u0004 \u0005[אותו]?\u0006 הלא בודאי אין מקטירים אותו בתוך הכלי! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003מעלהו בכלי שרת\u0004 כדי \u0003להקטירו.\u0004","שנינו: \u0003ומולחו ונותנו על גבי האישים —\u0004 \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"וכל קרבן מנחתך במלח תמלח\"\u0004 (ויקרא ב, יג).","ועוד שנינו: \u0003קרב הקומץ שיריה נאכלין,\u0004 ושואלים: \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"והקטיר הכהן את אזכרתה\"\u0004 (ויקרא ב, ב), כלומר, הקומץ \u0003וכתיב\u0004 \u0005[ו\u0006אחר כך \u0005נאמר]\u0006 \u0003\"והנותרת מן המנחה לאהרן ולבניו\"\u0004 (ויקרא ב, ג).","ומה שאמרו \u0003קרב הקומץ —\u0004 \u0003למר כדאית ליה ולמר כדאית ליה\u0004 \u0005[לחכם זה כ\u0006דעה \u0005שיש לו\u0006 בענין זה, \u0005ולחכם זה כ\u0006דעה \u0005שיש לו\u0006 בענין\u0005].\u0006 \u0003דאיתמר\u0004 \u0003[שנאמר]:\u0004 שחלקו חכמים בדבר: \u0003הקומץ מאימתי מתיר שיריים באכילה\u0004 לכהנים? \u0003ר' חנינא אמר: משתשלוט בו האור\u0004 (האש), כלומר, כבר משמתחיל לבעור, \u0003ר' יוחנן אמר: משתיצת האור ברובו\u0004 של הקומץ. ועל כל פנים, כשמגיע הזמן הראוי, בין לשיטה זו ובין לשיטה זו, מותרים הכהנים באכילת השיריים.","שנינו: \u0003ורשאין הכהנים ליתן לתוכו יין ושמן ודבש.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]?\u0006 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בקשר למתנות כהונה: \u0003\"\u0004לך נתתים \u0003למשחה\"\u0004 (במדבר יח, ח) וכוונתו — \u0003לגדולה, כדרך שהמלכים אוכלין.\u0004","עוד שנינו: \u0003ואין אסורין אלא מלחמץ\u0004, ומקור הדבר הוא במה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 לגבי מנחות: \u0003\"לא תאפה חמץ חלקם\u0004 נתתי אותה מאשי\u0003\"\u0004 (ויקרא ו, י), ו\u0003אמר ר' שמעון בן לקיש:\u0004 יש לדרוש את הכתוב כאילו היה ההפסק לאחר המלה \"חלקם\" ולפרש: \u0003אפילו חלקם\u0004 של הכהנים \u0003לא תאפה חמץ.\u0004","שנינו במשנה: \u0003כל המנחות\u0004 טעונות שמן ולבונה. ושואלים: \u0003ו\u0004כי \u0003כל המנחות טעונות שמן ולבונה? והאיכא\u0004 \u0005[והרי יש]\u0006 \u0003מנחת חוטא, דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"לא ישים עליה שמן ולא יתן עליה לבנה\"\u0004 (ויקרא \u0003ה, יא)! ומשיבים:\u0004","\u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003כל המנחות טעונות שמן ולבונה, ובאות מן החיטין, ובאות סלת. מנחת חוטא, אף על פי שאינה טעונה שמן ולבונה\u0004 מכל מקום \u0003באה מן החטין ובאה סלת.\u0004 וכן \u0003מנחת העומר, אף על פי שהיא באה מן השעורין —\u0004 \u0003טעונה שמן ולבונה ובאה גרש\u0004 שהוא ה\"סולת\" שבשעורים. \u0003וזו,\u0004 מנחת סוטה, \u0003אינה טעונה לא שמן ולא לבונה, ובאה מן השעורין, ובאה קמח.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אמר ר' שמעון: בדין הוא,\u0004 כלומר, מן הדין היה \u0003שתהא מנחת חוטא טעונה שמן ולבונה, שלא יהא חוטא נשכר\u0004 שמרוויח על ידי שאינו צריך להביא מכספו מנחה על כל מרכיביה. \u0003ומפני מה אינה טעונה —\u0004 \u0003שלא יהא קרבנו מהודר.\u0004","\u0003ו\u0004כן \u0003בדין הוא שתהא חטאת חלב\u0004 כלומר, חטאת שמביא אדם על שאכל חלב בשגגה, וכיוצא בו בשאר חטאים שמקור איסורם הוא במצוות \"לא תעשה\" שעשה בשגגה, שתהא \u0003טעונה נסכים\u0004 (סולת, שמן, ויין שמנסכים על גבי המזבח), \u0003שלא יהא חוטא נשכר\u0004 בזה שאינו מביא נסכים, \u0003ומפני מה אינה טעונה —\u0004 \u0003שלא יהא קרבנו מהודר.\u0004","\u0003אבל חטאתו של מצורע ואשמו —\u0004 \u0003טעונין נסכים, לפי שאין באין על חטא.\u0004 ותוהים: \u0003איני\u0004 \u0005[האם כן הוא]\u0006 וכי הצרעת אינה באה על חטא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' שמואל בר נחמני אמר ר' יונתן: על שבעה דברים\u0004 שאדם חוטא בהם \u0003נגעים באין\u0004 עליו, משמע שהמצורע חוטא הוא! ומשיבים: \u0003התם מנגעיה הוא דאיכפר ליה\u0004 \u0005[שם,\u0006 במצורע, \u0005מ\u0006שעה שקיבל את \u0005נגעו הוא שנתכפר לו]\u0006 מן החטא, \u0003כי מייתי\u0004 \u0005[כאשר\u0006 הוא \u0005מביא]\u0006 \u0003קרבן —\u0004 \u0003לאשתרויי\u0004 \u0005[על מנת להתירו]\u0006 לאכול \u0003בקדשים הוא דקא מייתי\u0004 \u0005[שמביא]\u0006 ולא על החטא.","ושואלים: \u0003אלא מעתה\u0004 לפי עקרון זה, \u0003חטאת נזיר תהא טעונה נסכים, לפי שאינה באה על חטא!\u0004 ומשיבים: \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כר' אלעזר הקפר,\u0004 ש\u0003אמר: נזיר נמי\u0004 \u0005[גם כן]\u0006 \u0003חוטא הוא,\u0004 שמצער עצמו בנזירותו.","שנינו במשנה, \u0003רבן גמליאל אומר: כשם\u0004 שמעשיה מעשה בהמה כך קרבנה קרבן בהמה. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להן רבן גמליאל לחכמים: סופרים, הניחו לי ואדרשנה כמין חומר\u0004 (כמין טבעת מקושטת) כלומר, על דרך הרמז."],["\u0003דשמעיה\u0004 \u0005[ששמע אותו]\u0006 את \u0003ר' מאיר דקאמר\u0004 \u0005[שאומר]\u0006 טעם לדבר: \u0003היא האכילתו מעדני עולם —\u0004 \u0003לפיכך קרבנה מאכל בהמה. אמר ליה\u0004 \u0005[לו]\u0006 לר' מאיר: \u0003התינח\u0004 \u0005[\u0006דבר \u0005זה נוח]\u0006 כשאתה מדבר על סוטה \u0003עשירה,\u0004 אולם בסוטה \u0003עניה מאי איכא למימר\u0004 \u0005[מה יש לומר],\u0006 הרי זו לא האכילתו מאכלים משובחים, לפי שאין ברשותה! \u0003אלא\u0004 כך צריך לפרש: \u0003כשם שמעשיה מעשה בהמה —\u0004 \u0003כך קרבנה\u0004 משעורים שהוא \u0003מאכל בהמה.\u0004","\u0003היה\u0004 הכהן \u0003מביא פילי\u0004 (קערה) \u0003של חרס ונותן לתוכה חצי לוג מים מן הכיור. ר' יהודה אומר: רביעית\u0004 מים בלבד. ומדוע, \u0003כשם שממעט בכתב\u0004 שלשיטתו כותבים במגילת סוטה פחות ממה שסבורים שאר חכמים, \u0003כך ממעט במים.\u0004","לאחר מכן \u0003נכנס\u0004 הכהן \u0003להיכל ופנה לימינו, ומקום היה שם\u0004 בריצפת ההיכל, בגודל \u0003אמה על אמה, וטבלא\u0004 (לוח) \u0003של שיש\u0004 על גביו, \u0003וטבעת היתה קבועה בה\u0004 בטבלה ונעזר בה \u0003כשהוא מגביה\u0004 את הטבלה, \u0003ונוטל עפר\u0004 כלשהו \u0003מתחתיה, ונותן\u0004 אותו לתוך המים שבכלי \u0003כדי\u0004 השיעור \u0003שיראה\u0004 העפר \u0003על המים, שנאמר: \"ומן העפר אשר יהיה בקרקע המשכן יקח הכהן ונתן אל המים\"\u0004 (במדבר ה, יז).","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003פילי\u0004 זו שבה היו מביאים מים מן הכיור \u0003של חרס חדשה\u0004 היתה, אלו \u0003דברי ר' ישמעאל.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל\u0004 שלדעתו היא צריכה להיות חדשה? ומשיבים: \u0003גמר\u0004 \u0005[למד]\u0006 בגזירה שווה \u0003\"כלי\" \"כלי\" ממצורע, מה להלן,\u0004 במצורע, קערת \u0003חרס חדשה —\u0004 \u0003אף כאן\u0004 קערת \u0003חרס חדשה.\u0004","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם,\u0006 במצורע, \u0005מניין לנו]\u0006 שצריכה להיות חדשה? ומשיבים: \u0003דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"ושחט את הצפר האחת אל כלי חרש על מים חיים\"\u0004 (ויקרא יד, נ), \u0003מה מים חיים\u0004 הם מים \u0003שלא נעשתה בהן מלאכה,\u0004 שאם נעשתה בה מלאכה אינם נקראים \"חיים\" — \u0003אף כלי\u0004 שנאמר במצורע אינו אלא זה \u0003שלא נעשתה בו מלאכה\u0004 והוא עדיין חדש.","ושואלים: \u0003אי\u0004 \u0005[אם\u0006 כן\u0005]\u0006 על פי גזירה שווה זו אפשר גם ללמוד: \u0003מה להלן מים חיים,\u0004 כלומר, מים היוצאים ממעיין נובע, \u0003אף כאן\u0004 בסוטה יצטרכו \u0003מים חיים?!\u0004","ומשיבים: \u0003לר' ישמעאל הכי נמי\u0004 \u0005[כך\u0006 הוא \u0005גם כן].\u0006 ש\u0003אמר ר' יוחנן: מי כיור,\u0004 המים שבכיור המקדש, \u0003ר' ישמעאל אומר: מי מעיין הן,\u0004 שצריכים מים אלה לבוא מן המעיין, \u0003וחכמים אומרים:\u0004 מים אלה אינם חייבים להיות מי מעיין, אלא אף \u0003משאר מימות הן.\u0004","על הגזירה השווה תוהים: הלא \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005להקשות]\u0006 עליה: \u0003מה למצורע —\u0004 \u0003שכן טעון\u0004 עוד מצוות יתירות: \u0003עץ ארז, ואזוב, ושני תולעת!\u0004","\u0003אמר רבה, אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת סוטה: \u0003\"בכלי חרש\"\u0004 (במדבר ה, יז) ולא פירש תחילה שצריך לקחת כלי חרס, הרי זה כאילו היה ממשיך ומתייחס ל\u0003כלי שאמרתי לך כבר,\u0004 כעין הכלי שנאמר בדיני מצורע.","\u0003אמר רבא: לא שנו\u0004 במשנה כלי חרס \u0003אלא\u0004 דווקא זה \u0003שלא נתאכמו\u0004 (הושחרו) \u0003פניו\u0004 של הכלי על ידי האש, \u0003אבל\u0004 אם \u0003נתאכמו פניו —\u0004 \u0003פסולין\u0004 המים לדברי הכל, ואף אם אין צורך בכלי חדש. \u0003מאי טעמא\u0004 \u0005[מה הטעם] —\u0006 \u0003דומיא דמים\u0004 \u0005[בדומה למים],\u0006 \u0003מה מים\u0004 שנאמרו אינם אלא אלו \u0003שלא נשתנו\u0004 במראיהם — \u0003אף כלי\u0004 דווקא זה \u0003שלא נשתנה\u0004 במראהו.","מתוך הלכה זו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא\u0004 שאלה זו: \u0003נתאכמו\u0004 (הושחרו) כלי החרס \u0003והחזירן לתוך כבשן האש ונתלבנו\u0004 בו, וסרה מהם השחרות, \u0003מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003כיון דאידחו אידחו\u0004 \u0005[שנדחו נדחו]\u0006 ואינם ראויים עוד, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דהדור הדור\u0004 \u0005[שחזרו\u0006 למראיהם \u0005חזרו\u0006 להכשרם\u0005]?\u0006","ומנסים לפתור בעיה זו, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו, \u0003ר' אלעזר אומר: עץ ארז ואזוב ושני תולעת שהפשיל בהן קופתו לאחוריו\u0004 (קשר בהם את סלו כדי להחזיקו מאחוריו) — \u0003פסולין\u0004 לטהרת המצורע. \u0003והא התם הדרי ומפשטי\u0004 \u0005[והרי שם\u0006 הם \u0005חוזרים ונפשטים]\u0006 ונעשים כאילו לא השתמש בהם!","ומשיבים: \u0003התם דאיקלוף איקלופי\u0004 \u0005[שם\u0006 מדובר \u0005ש\u0006על ידי שימוש זה \u0005נתקלפו]\u0006 ואינם חוזרים שוב למה שהיו, ואם כן אין מכאן ראיה.","שנינו במשנה: \u0003נכנס להיכל ופנה לימינו.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003כל פינות\u0004 (פניות) \u0003שאתה פונה לא יהו אלא דרך ימין.\u0004","ועוד שנינו שם: \u0003מקום היה שם אמה\u0004 על אמה וכו'. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על מה שנאמר: \u0003\"ומן העפר אשר יהיה\"\u0004 (במדבר ה, יז), \u0003יכול יתקן\u0004 (יכין) עפר \u0003מבחוץ ויכניס —\u0004","\u0003תלמוד לומר: \"בקרקע המשכן\"\u0004 (במדבר ה, יז). \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"בקרקע המשכן\" —\u0004 \u0003יכול יחפור בקרדומות\u0004 מן הקרקע — \u0003תלמוד לומר: \"אשר יהיה\",\u0004 שהוא מצוי כבר. \u0003הא כיצד? יש שם\u0004 בקרקע המשכן עפר מוכן — \u0003הבא\u0004 משם, \u0003אין שם —\u0004 \u0003תן שם\u0004 עפר ממקום אחר.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 מה שנאמר \u0003\"ומן העפר אשר יהיה\"\u0004 (במדבר ה, יז) — \u0003מלמד שהיה מתקן\u0004 עפר \u0003מבחוץ ומכניס.\u0004 ומה שנאמר \u0003\"בקרקע המשכן\", איסי בן יהודה אומר:\u0004 לא לזה בא הכתוב, אלא \u0003להביא קרקע\u0004"],["\u0003שילה נוב וגבעון\u0004 שהיה המשכן בהם, \u0003ובית עולמים\u0004 (המקדש בירושלים), אף שאינם המשכן שבמדבר.","\u0003איסי בן מנחם אומר: אינו צריך\u0004 ללימוד זה מייתור הכתוב, שהרי קל וחומר הוא: \u0003ומה בטומאה קלה,\u0004 כלומר, האיסור להיכנס בטומאה למקום הקודש, שאין בו מיתת בית דין \u0003לא חלק הכתוב\u0004 בין המשכן שבמדבר לבין השאר — \u0003בטומאת אשת איש חמורה,\u0004 שאם התברר שזינתה עונשה בחנק, \u0003לא כל שכן? אם כן מה תלמוד לומר \"בקרקע המשכן\"\u0004 — הכוונה היא \u0003שלא יביא\u0004 עפר \u0003מתוך קופתו\u0004 (סלו) ישר לתוך הכלי עם מי הסוטה, אלא יניחנו על קרקע המשכן וירים אותו משם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אם \u0003אין שם\u0004 בקרקע המקדש \u0003עפר, מהו שיתן\u0004 במקומו \u0003אפר?\u0004 ומעירים: \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003בית שמאי לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 כי בכלל \u0003לא מצינו אפר שקרוי \"עפר\".\u0004","\u0003תיבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה, הרי זה \u0003אליבא\u0004 \u0005[לשיטת]\u0006 \u0003בית הלל דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003מצינו אפר שקרוי \"עפר\",\u0004 לענין אפר פרה אדומה, ודינם שווה לענין כיסוי הדם, \u0003מאי\u0004 \u0005[מהו]\u0006 לענייננו? וצדדי השאלה האם נאמר \u0003אף על גב דאיקרי\u0004 \u0005[אף על פי ש\u0006אפר \u0005נקרא]\u0006 \u0003\"עפר\"\u0004 במקום אחר, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003\"בקרקע המשכן\" כתיב\u0004 \u0005[נאמר],\u0006 ולפי זה הכוונה דווקא לעפר שהוא מגוף הקרקע, \u0003או דילמא האי\u0004 \u0005[שמא זה]\u0006 שנאמר \u0003\"בקרקע המשכן\" —\u0004 \u0003לכד\u0004ברי \u0003איסי בן יהודה, ולכד\u0004ברי \u0003איסי בן מנחם הוא דאתי\u0004 \u0005[שבא]\u0006 הכתוב?","ומשיבים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע],\u0006 פתרון לדבר ממה ש\u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: בשלשה מקומות הלכה עוקבת,\u0004 כלומר, משנה ומבטלת את משמעות ה\u0003מקרא.\u0004 כיצד?","\u0003התורה אמרה\u0004 \u0003\"\u0004ושפך את דמו וכסהו \u0003בעפר\"\u0004 (ויקרא יז, יג), \u0003והלכה —\u0004 \u0003בכל דבר\u0004 הדומה לעפר. וכן \u0003התורה אמרה ב\u0004נזיר \u0003\"תער\u0004 לא יעבור על ראשו\u0003\"\u0004 (במדבר ו, ה), \u0003והלכה —\u0004 \u0003בכל דבר\u0004 אסור להסיר שערו, ולוקה על כך. \u0003התורה אמרה\u0004 בגט אשה \"וכתב לה \u0003ספר\u0004 כריתות\" (דברים כד, א), \u0003והלכה —\u0004 \u0003בכל דבר\u0004 תלוש שאפשר לכתוב עליו.","\u0003ואם איתא\u0004 \u0005[ישנה]\u0006 הלכה זו שאפשר לשים אפר במקום עפר — \u0003ליחשוב נמי האי\u0004 \u0005[שימנה גם\u0006 את \u0005זה]!\u0006","ודוחים: אין זו ראיה, כי לא נמנו הכל אלא \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר,\u0004 שיש עוד דוגמאות כאלה שלא נמנו במפורש. ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003שייר\u0004 עוד שאתה אומר \u0003דהאי\u0004 \u0005[ש\u0006את \u0005זו]\u0006 \u0003שייר?\u0004 ומשיבים: \u0003שייר מצורע. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר \u0003\"והיה ביום השביעי יגלח את כל שערו\"\u0004 (ויקרא יד, ט) — הרי זה \u0003כלל, \"את ראשו ואת זקנו ואת גבת עיניו\"\u0004 (ויקרא יד, ט) — הרי זה \u0003פרט, \"ואת כל שערו יגלח\"\u0004 (ויקרא יד, ט) — \u0003חזר וכלל!\u0004 ובדרך מדרש ההלכה \u0003כלל ופרט וכלל —\u0004 \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה דן אלא כעין הפרט: מה פרט מפורש\u0004 דבר שהוא \u0003מקום כינוס שער, ונראה\u0004 (גלוי) — \u0003אף כל מקום כינוס שער ונראה.\u0004","\u0003מה רבי\u0004 \u0005[ריבה]\u0006 בכך הכלל — \u0003רבי\u0004 \u0005[ריבה]\u0006 את \u0003שער הרגלים\u0004 (שיער הערוה). \u0003מאי\u0004 \u0005[מה]\u0006 \u0003מיעט\u0004 הפרט — \u0003מיעט\u0004 שיער של \u0003בית השחי\u0004 שאינו נראה, \u0003ודכוליה גופיה\u0004 \u0005[ושל כל גופו]\u0006 שאינו מכונס.","\u0003ו\u0004בכל זאת \u0003הלכתא\u0004 \u0005[ההלכה]\u0006 היא: \u0003מגלח כדלעת,\u0004 כלומר, את כל גופו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בא לו להקיף\u0004 (לגלח) \u0003את המצורע —\u0004 \u0003מעביר תער על כל בשרו, וקתני סיפא\u0004 \u0005[ושנה\u0006 ב\u0005סופה]\u0006 של אותה משנה: \u0003וביום השביעי מגלחו תגלחת שניה כתגלחת ראשונה\u0004 כי בתגלחת הראשונה לטהרתו לא נאמרו כלל ופרט אלה אלא \"כל שערו\" (ויקרא יד, ח) ובודאי מגלח הכל.","\u0003אמר רב נחמן בר יצחק:\u0004 אין להחשיב את דין מצורע כשיור, שכן \u0003כי קא חשיב\u0004 \u0005[כאשר\u0006 התנא \u0005מונה],\u0006 הרי הוא מונה מקרים ש\u0003הלכה\u0004 מן התורה \u0003עוקבת\u0004 (משנה ומבטלת) \u0003מקרא\u0004 — ואילו \u0003הא\u0004 \u0005[זו]\u0006 \u0003עוקבת מדרבנן\u0004 \u0005[מדרש חכמים]\u0006 \u0003היא.\u0004","\u0003רב פפא אמר\u0004 באופן אחר: \u0003כי קא חשיב\u0004 \u0005[כאשר\u0006 הוא \u0005מונה]\u0006 \u0003הלכה עוקבת ועוקרת\u0004 את הדין שבמקרא, \u0003הא\u0004 \u0005[זו]\u0006 בגילוח מצורע \u0003עוקבת ומוספת היא\u0004 שהרי אינה מבטלת את הדין האמור בתורה אלא רק מוסיפה עליו.","\u0003רב אשי אמר\u0004 באופן אחר: \u0003הא מתניתא מני\u0004 \u0005[ברייתא זו\u0006 בדיני מצורע כשיטת \u0005מי היא] —\u0006 שיטת \u0003ר' ישמעאל היא, דדריש\u0004 \u0005[ש\u0006הוא \u0005דורש]\u0006 את הכתוב בדרך הלימוד של \u0003כללי ופרטי\u0004 \u0005[כללים ופרטים],\u0006 ולפי שיטה זו באמת אין המצורע מגלח את כל שערו אלא רק שיער כנוס ונראה."],["\u0003כדלעת, מני\u0004 \u0005[\u0006שיטת \u0005מי היא] —\u0006 שיטת \u0003ר' עקיבא היא, דדריש\u0004 \u0005[ש\u0006הוא \u0005דורש]\u0006 את התורה לפי השיטה של \u0003ריבויי ומיעוטי\u0004 \u0005[ריבויים ומיעוטים].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 אחרת: מה שנאמר \u0003\"והיה ביום השביעי יגלח את כל שערו\"\u0004 (ויקרא יד, ט) הרי ביטוי זה \u0003ריבה\u0004 את כל שערותיו. \u0003\"את ראשו ואת זקנו ואת גבת עיניו\"\u0004 (ויקרא יד, ט) — \u0003מיעט. \"ואת כל שערו יגלח\"\u0004 (ויקרא יד, ט) — \u0003חזר וריבה.\u0004 והכלל בשיטת לימוד זו ש\u0003ריבה ומיעט וריבה —\u0004 \u0003ריבה הכל.\u0004","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003ריבה —\u0004 \u0003ריבה\u0004 את השיער \u0003דכוליה גופיה\u0004 \u0005[של כל גופו],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 בכל זאת — \u0003מיעט שיער שבתוך החוטם,\u0004 שאותו אינו צריך לגלח ואין איפוא להקשות על ר' ישמעאל מדברים שהם כשיטת ר' עקיבא.","ושואלים: בסופו של דבר \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה]\u0006 על שאלה זו ששאלנו בענין אפר במקום עפר לצורך השקאת סוטה? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר רב הונא בר אשי אמר רב: אין שם עפר —\u0004 \u0003מביא רקבובית\u0004 רקב שנוצר על ידי \u0003ירק, ומקדש\u0004 את המים. כלומר, מכשירם לצורך זה. הרי שאין צורך בעפר דווקא.","ודוחים: \u0003ולא היא,\u0004 אין מכאן ראיה, ומדוע? \u0003רקבובית\u0004 \u0003ירק הוא\u0004 שכשירה משום \u0003דהואי\u0004 \u0005[שנעשית]\u0006 לבסוף \u0003עפר,\u0004 ואילו \u0003אפר לא הואי\u0004 \u0005[נעשה]\u0006 \u0003עפר,\u0004 ואין איפוא להביא ראיה מכאן.","שנינו במשנה: כמה עפר נותן — \u0003כדי שיראה על המים. תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003שלשה צריכין שיראו: עפר סוטה, ואפר פרה\u0004 במי חטאת, \u0003ורוק יבמה\u0004 היורקת לפני הדיינים בזמן שחולצת. \u0003משום\u0004 (בשם) \u0003ר' ישמעאל אמרו: אף דם צפור\u0004 של מצורע צריך להיראות על פני המים שבכלי.","ומבארים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וטבל אתם בדם הצפר\"\u0004 (ויקרא יד, \u0003נא),\u0004 \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"בדם\", יכול בדם ולא במים\u0004 כלל — \u0003תלמוד לומר: \"במים\"\u0004 (ויקרא יד, \u0003נא).\u0004 \u0003אי\u0004 \u0005[אם]\u0006 ב\u0003מים, יכול במים ולא בדם —\u0004 \u0003תלמוד לומר: \"בדם\". הא כיצד\u0004 יתקיימו שני הכתובים? \u0003מביא מים\u0004 בכמות כזו \u0003שדם ציפור\u0004 עדיין \u0003ניכר בהן, וכמה\u0004 הם — \u0003רביעית\u0004 הלוג.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאינם מצריכים שייראה דם הציפור, כיצד הם מבינים את הכתוב — הם אומרים כי הכתוב \u0003ההוא\u0004 נצרך \u0003לגופיה\u0004 \u0005[לגופו],\u0006 \u0003דהכי קאמר רחמנא\u0004 \u0005[שכך אמרה תורה]:\u0006 \u0003אטביל\u0004 \u0005[הטבל]\u0006 את הציפור \u0003בדם ובמים\u0004 יחד.","\u0003ור' ישמעאל\u0004 אומר: \u0003אם כן,\u0004 שרק לצורך זה בא הכתוב, \u0003לכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 \u0003\"וטבל בהם\",\u0004 ומה ששנה הכתוב ואמר \u0003\"בדם\u0004 הציפור \u0003ובמים\"\u0004 \u0003למה לי —\u0004 \u0003ל\u0004למד שיהא הדם \u0003ניכר.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים על כך: \u0003אי כתב רחמנא\u0004 \u0005[אילו היתה כותבת התורה]\u0006 \u0003\"וטבל בהם\" —\u0004 \u0003הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003האי לחודיה והאי לחודיה\u0004 \u0005[זה לחוד וזה לחוד],\u0006 לכן \u0003כתב רחמנא\u0004 \u0005[כתבה תורה]\u0006 \u0003\"בדם\u0004 הציפור \u0003ובמים\"\u0004 כדי לחייב \u0003לערבן\u0004 יחד.","ו\u0003ר' ישמעאל\u0004 סבור כי על המצוה \u0003לערבן קרא אחרינא כתיב\u0004 \u0005[כתוב אחר נאמר]\u0006 \u0003\"ושחט את הצפר האחת\u0004 אל כלי חרש על מים חיים\u0003\"\u0004 (ויקרא יד, \u0003נ), הרי שהדם נופל לתוך המים ומעורב בהם.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 אומרים: \u0003אי מההוא הוה אמינא\u0004 \u0005[אם מאותו\u0006 פסוק \u0005הייתי אומר]:\u0006 \u0003לישחטיה\u0004 \u0005[שישחוט]\u0006 את הציפור \u0003סמוך למנא\u0004 \u0005[לכלי]\u0006 שבו המים \u0003ונינקטינהו\u0004 \u0005[ויאחוז]\u0006 \u0003לוורידין\u0004 שלא יצא הדם, \u0003ולקבליה\u0004 \u0005[ויקבלו]\u0006 \u0003לדם במנא אחרינא\u0004 \u0005[בכלי אחר],\u0006 ויהיו כלים מיוחדים לדם ולמים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003הכתוב שצריך לערבם יחד, וגם לשחוט לתוך הכלי.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' ירמיה מר' זירא:\u0004 היתה ציפור \u0003גדולה\u0004 שלה דם רב \u0003ומדחת את המים\u0004 שאין המים ניכרים בדם, או להיפך, ציפור \u0003קטנה ונדחית מפני המים\u0004 שאין הדם ניכר במים, \u0003מהו\u0004 הדין בכגון זה?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לאו אמינא לך לא תפיק נפשך לבר מהילכתא\u0004 \u0005[\u0006האם \u0005לא אמרתי לך אל תוציא את עצמך מחוץ להלכה],\u0006 כלומר, אל תנסה לערער על תחומי ההלכה, \u0003בצפור דרור שיערו רבנן\u0004 \u0005[חכמים],\u0006 \u0003אין לך\u0004 ציפור דרור \u0003גדולה\u0004 \u0003כל כך\u0004 \u0003שמדחת את המים, ואין לך קטנה\u0004 כל כך \u0003שנדחית מפני המים.\u0004","ועוד לענין עפר סוטה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הקדים עפר למים —\u0004 \u0003פסול, ור' שמעון מכשיר.\u0004 ומבארים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' שמעון —\u0004","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 לענין פרה אדומה \u0003\"ולקחו לטמא מעפר שרפת החטאת\u0004 ונתן עליו מים חיים אל כלי\u0003\"\u0004 (במדבר יט, יז), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון: וכי עפר הוא? והלא אפר הוא!\u0004 אלא \u0003שינה הכתוב במשמעו\u0004 ולא נאמר \"אפר\" במפורש אלא \"עפר\" \u0003לדון הימנו גזירה שוה; נאמר כאן\u0004 בפרה אדומה \u0003\"עפר\" ונאמר להלן\u0004 בסוטה \u0003\"עפר\", מה להלן\u0004 בסוטה נותן \u0003עפר על גבי מים\u0004 כלשון הכתוב \"ומן העפר... יקח הכהן ונתן אל המים\" (במדבר ה, יז) — \u0003אף כאן\u0004 בפרה אדומה \u0003עפר\u0004 (אפר) \u0003על גבי מים.\u0004","\u0003ומה כאן\u0004 בפרה אדומה אם \u0003הקדים עפר למים —\u0004 \u0003כשר, אף להלן\u0004 בסוטה \u0003הקדים עפר למים —\u0004 \u0003כשר.\u0004","ושואלים: \u0003והתם מנלן\u0004 \u0005[ושם\u0006 בפרה אדומה \u0005מניין לנו]\u0006 שאם הקדים עפר למים כשר? ומשיבים: \u0003תרי קראי כתיבי\u0004 \u0005[שני מקראות כתובים];\u0006 \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \"ולקחו לטמא מעפר שרפת החטאת ונתן \u0003עליו\u0004 מים חיים\" (במדבר יט, יז), \u0003אלמא\u0004 \u0005[מכאן]\u0006 שה\u0003אפר ברישא\u0004 \u0005[בתחילה],\u0006 \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 באותו פסוק: \u0003\"מים חיים אל כלי\",\u0004 לומר שיהיו המים חיים וצלולים ניתנים לתוך הכלי שעדיין אין כלום בכלי, \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003מים ברישא\u0004 \u0005[בתחילה],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 אתה מקיים את שניהם? \u0003רצה —\u0004 \u0003זה נותן\u0004 תחילה, \u0003רצה —\u0004 \u0003זה נותן.\u0004","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 הפוסלים סבורים כי מה שנאמר \u0003\"אל כלי\" —\u0004 \u0003דוקא\u0004 הוא, ומה שנאמר \u0003\"עליו\"\u0004 — הרי זה בא ללמד שמצוה \u0003לערבן\u0004 את האפר במים.","ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 אחרת: \u0003\"עליו\"\u0004 כוונתו \u0003דוקא\u0004 שיהא אפר תחילה, ומה שנאמר \u0003\"אל כלי\" —\u0004 \u0003שתהא חיותן בכלי,\u0004 שהמים יינתנו אל הכלי בעודם חיים, כלומר, במישרין מן המעיין ולא מכלי אחר!","ומשיבים: \u0003מה מצינו בכל מקום\u0004 (כגון בסוטה) שהעפר שהוא \u0003מכשיר\u0004 את המים לצורך המצוה נמצא \u0003למעלה, אף כאן\u0004 בפרה, האפר ה\u0003מכשיר\u0004 את המים להזאה \u0003למעלה.\u0004"],["\u0003א משנה\u0004 \u0003בא לו\u0004 הכהן \u0003לכתוב את המגילה, מאיזה מקום\u0004 בפרשת סוטה האמורה בתורה (במדבר פרק ה) \u0003הוא כותב?\u0004","— \u0003מ\"ואם לא שכב איש\" וגו',\u0004 וממשיך \u0003\"ואת כי שטית תחת אישך\"\u0004 וכו',","\u0003ואינו כותב \"והשביע הכהן את האשה\", וכותב \"יתן ה' אותך לאלה ולשבעה... ובאו המים המאררים האלה במעיך לצבות בטן ולנפל ירך\"\u0004 (\u0003במדבר ה׳:כ״ב, פסוקים יט-כב),\u0004 \u0003ואינו כותב \"ואמרה האשה אמן אמן\"\u0004 (\u0003במדבר ה, כב).\u0004","\u0003ר' יוסי אומר: לא היה מפסיק,\u0004 אלא כותב את כל האמור בפרשה.","\u0003ר' יהודה אומר: כל עצמו\u0004 (בכלל) \u0003אינו כותב אלא \"יתן ה' אותך לאלה ולשבעה וגו' ובאו המים המאררים האלה במעיך\".\u0004 ומסיימת המשנה: \u0003ואינו כותב \"ואמרה האשה אמן אמן\"\u0004 (\u0003במדבר ה, כב).\u0004","בביאור המחלוקת במשנה שואלים: \u0003במאי קא מיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון, \u0005חלוקים\u0006 התנאים\u0005]\u0006 שבמשנה? ומסבירים: \u0003בהאי קרא קמיפלגי\u0004 \u0005[בכתוב זה\u0006 הם \u0005חלוקים],\u0006 נאמר: \u0003\"וכתב את האלת האלה הכהן בספר\"\u0004 (במדבר ה, כג);","\u0003ר' מאיר\u0004 התנא הראשון במשנתנו \u0003סבר: \"אלות\"\u0004 משמעו \u0003אלות\u0004 (קללות) \u0003ממש, \"האלות\"\u0004 בתוספת ה\"א הידיעה — \u0003לרבות קללות הבאות מחמת ברכות.\u0004 כלומר, גם ברכות הכתובות בפרשה שהצד השלילי שלהן הוא קללות. שאם אכן חטאה יבוא עליה היפך הברכה — גם את זאת כותב הכהן. \u0003\"אלה\"\u0004 שהוא לשון מיעוט — \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קללות שבמשנה תורה,\u0004 שאינו כותב אותן למרות שגם הן קרויות \"אלות\". \u0003\"האלה\"\u0004 בתוספת ה\"א הידיעה — \u0003למעוטי\u0004 \u0005[למעט]\u0006 גם \u0003צוואות\u0004 (חלק המצוות שבפרשה) \u0003וקבלות אמן\u0004 שעל ידי האשה שאינו כותב גם אותן.","\u0003ור' יוסי\u0004 דורש: \u0003כולהו כדקאמרת\u0004 \u0005[הכל כפי שאתה,\u0006 ר' מאיר, \u0005אומר],\u0006 אלא נאמר \u0003\"את\"\u0004 שהיא לשון ריבוי — \u0003לרבות צוואות וקבלות.\u0004","\u0003ור' מאיר —\u0004 \u0003אתים לא דריש\u0004 \u0005[דורש]\u0006 כלשון ריבוי.","\u0003ור' יהודה —\u0004 \u0003כולהו במיעוטי דריש להו\u0004 \u0005[כולם ב\u0006דרך של \u0005מיעוטים\u0006 הוא \u0005דורש אותם]:\u0006 \u0003\"אלות\"\u0004 — הריהן \u0003אלות ממש, \"האלות\" —\u0004 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קללות הבאות מחמת ברכות, \"אלה\" —\u0004 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003קללות שבמשנה תורה, \"האלה\" —\u0004 \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003צוואות וקבלות.\u0004","ושואלים: \u0003ור' מאיר, מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003האי\u0004 \u0005[זו]\u0006 \u0003ה\"י\u0004 של \"האלות\" \u0003דמרבי ביה\u0004 \u0005[שמרבה בו],\u0006 שלומד ממנה לרבות קללות הבאות מחמת ברכות, \u0003ומאי שנא\u0004 \u0005[ומה שונה]\u0006 \u0003האי\u0004 \u0005[זו]\u0006 \u0003ה\"י\u0004 של \"האלה\" \u0003דמעיט ביה\u0004 \u0005[שממעט בו]\u0006 צוואות וקבלת אמן?","ומשיבים: \u0003ה\"י דגביה דריבויא\u0004 \u0005[שאצל, ש\u0006ליד לשון \u0005ריבוי] —\u0006 \u0003ריבויא\u0004 \u0005[ריבוי]\u0006 \u0003היא, ה\"י דגביה דמיעוטא\u0004 \u0005[שאצל מיעוט] —\u0006 \u0003מיעוטא\u0004 \u0005[מיעוט\u0006 היא\u0005].\u0006 וכיון ש\"אלה\" היא לשון מיעוט, גם הה\"א שאצלה ממעט.","ושואלים: \u0003והא לית ליה\u0004 \u0005[והרי אין לו,\u0006 אינו מקבל\u0005]\u0006 \u0003ר' מאיר\u0004 את השיטה ש\u0003מכלל לאו אתה שומע הן,\u0004 ואם כן מדוע צריך לכתוב ברכות והרי לשיטתו לא משמע מהם קללות?","\u0003אמר ר' תנחום: \"הנקי\"\u0004 (\u0003במדבר ה, יט)\u0004 \u0003כתיב\u0004 \u0005[נאמר],\u0006 שהוא דורשו כאילו היה כתוב בח', לשון חנק, ומצרף אליה את תחילת הפסוק הבא, והרי זה כאילו נאמר \"חנקי ואת כי שטית תחת אישך\".","\u0003דריש\u0004 \u0005[דרש]\u0006 \u0003ר' עקיבא: איש ואשה\u0004 הנשואים זה לזו, אם \u0003זכו\u0004 ואין בהם זנות — \u0003שכינה ביניהן,\u0004 כי מצטרפות האות יו\"ד שבמלה \"איש\" והאות ה\"א שבמלה \"אשה\" לשם ה' (י-ה). ואם \u0003לא זכו\u0004 — שם שמים מסתלק מהם, ונשארו בשניהם רק אותיות \"אש\", ולכן \u0003אש אוכלתן.\u0004","\u0003אמר רבא: ו\u0004האש של \u0003אשה עדיפא\u0004 \u0005[עדיפה,\u0006 חזקה ומיידית יותר\u0005]\u0006 \u0003מ\u0004זו של ה\u0003איש, מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר \u0005—\u0006 \u0003האי מצרף\u0004 \u0005[זה מצורף]\u0006 בכתוב, שבמלה \"אשה\" האותיות \"אש\" מצויות יחד, \u0003והאי לא מצרף\u0004 \u0005[וזה אינו מצורף]\u0006 שבמלה \"איש\" יש אות מפרידה ביניהם.","\u0003אמר רבא: מפני מה אמרה תורה הבא עפר לסוטה?\u0004 שאם \u0003זכתה\u0004 והתברר שלא זינתה — \u0003יוצא ממנה בן כאברהם אבינו, דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"\u0004ואנוכי \u0003עפר ואפר\"\u0004 (בראשית יח, כז), ואם \u0003לא זכתה —\u0004 \u0003תחזור לעפרה,\u0004 שמתה משתיית מי הסוטה.","ועוד \u0003דריש\u0004 \u0005[דרש]\u0006 \u0003רבא: בשכר שאמר אברהם אבינו \"ואנכי עפר ואפר\" זכו בניו לשתי מצות, אפר פרה ועפר סוטה.\u0004","ומקשים: \u0003והאיכא נמי\u0004 \u0005[והרי יש גם כן]\u0006 מצוה נוספת בעפר — \u0003עפר כיסוי הדם!\u0004","ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בכיסוי הדם אמנם \u0003הכשר מצוה איכא\u0004 \u0005[יש]\u0006 בכך, אבל \u0003הנאה ליכא\u0004 \u0005[אין],\u0006 משום שמצוות כיסוי הדם היא לאחר שכבר שחט ואין בה איפוא הנאה של תיקון.","ועוד \u0003דרש רבא: בשכר שאמר אברהם אבינו \"אם מחוט ועד שרוך נעל\"\u0004 \u0005(בראשית יד, כג)\u0006 וויתר על ממון שאינו שלו, \u0003זכו בניו לשתי מצות: חוט של תכלת ורצועה של תפלין.\u0004","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003רצועה של תפלין\u0004 יש בה ענין של מעלה וזכות, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וראו כל עמי הארץ כי שם ה' נקרא עליך\u0004 ויראו ממך\u0003\"\u0004 (דברים כח, י) \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר הגדול אומר: אלו תפלין שבראש.\u0004 משמע שיש בהם ענין של תפארת וגדולה.","\u0003אלא חוט של תכלת מאי היא\u0004 \u0005[מה הוא]\u0006 הדבר המיוחד בקיומה? ומשיבים: \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003היה ר' מאיר אומר: מה נשתנה תכלת מכל מיני צבעונין\u0004 שנבחר לציצית?","— \u0003מפני שהתכלת דומה\u0004 בצבעו \u0003לים, וים דומה לרקיע, ורקיע דומה לכסא הכבוד,\u0004 וראיה לכך — \u0003שנאמר: \"ויראו את אלהי ישראל ותחת רגליו כמעשה לבנת הספיר וכעצם השמים לטהר\"\u0004 (שמות כד, י), מכאן שהרקיע הוא כלבנת הספיר, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כמראה אבן ספיר דמות כסא\u0004 (יחזקאל א, כו), מכאן שכסא הכבוד הוא גם כלבנת הספיר, הרי שיש בתכלת אות של קשר לשכינה.","\u0003אינו כותב\u0004 מגילת סוטה \u0003לא על הלוח\u0004 של עץ, \u0003ולא על הנייר, ולא על\u0004"],["\u0003הדיפתרא\u0004 (עור שאינו מעובד כל צורכו) \u0003אלא על המגילה\u0004 של קלף, \u0003שנאמר: \"בספר\"\u0004 (במדבר ה, כג).","\u0003ואינו כותב לא בקומוס\u0004 (צבע העשוי משרף) \u0003ולא בקנקנתום\u0004 (גופרת נחושת), \u0003ולא בכל דבר\u0004 אחר \u0003שרושם\u0004 ואינו נמחק לגמרי, \u0003אלא בדיו\u0004 בלבד, \u0003שנאמר: \"ומחה\"\u0004 (במדבר ה, כג), שצריך להיות \u0003כתב שיכול למחות\u0004 במים.","\u0003אמר רבא: מגילת סוטה שכתבה בלילה —\u0004 \u0003פסולה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"תורה\" \"תורה\"; כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ועשה לה הכהן את כל התורה הזאת\"\u0004 (במדבר ה, ל), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"על פי התורה אשר יורוך ועל המשפט\"\u0004 (דברים יז, יא), \u0003מה משפט\u0004 הוא דווקא \u0003ביום —\u0004 \u0003אף מגילת סוטה\u0004 אינה נכתבת אלא \u0003ביום.\u0004","ואם \u0003כתבה למפרע\u0004 (שלא כסידרה) — \u0003פסולה, דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"וכתב את האלת האלה\"\u0004 (במדבר ה, כג), להדגיש שלא לשנות אלא \u0003כי דכתיבא\u0004 \u0005[כמו ש\u0006היא, המגילה, \u0005כתובה]\u0006 בתורה.","\u0003כתבה\u0004 את המגילה \u0003קודם שתקבל\u0004 הסוטה \u0003עליה שבועה —\u0004 \u0003פסולה\u0004 המגילה, \u0003שנאמר: \"והשביע\u0004 הכהן את האשה\u0003\"\u0004 (במדבר ה, כא) \u0003ו\u0004רק \u0003אחר כך\u0004 נאמר \u0003\"וכתב\"\u0004 (במדבר ה, כג).","\u0003כתבה\u0004 כדרך שכותבים \u0003איגרת\u0004 בלא שירטוט השורות — \u0003פסולה,\u0004 מדוע — \u0003\"בספר\" אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 שצריך להיות כתוב כדין ספר תורה והוא אינו נכתב אלא לאחר שירטוט."],["\u0003כתבה על שני דפין\u0004 שאינם צמודים זה לזה — \u0003פסולה.\u0004 כי \u0003\"ספר\"\u0004 שהוא \u0003אחד אמר רחמנא\u0004 \u0005[תורה]\u0006 \u0003ולא\u0004 שתהיה המגילה \u0003שנים ושלשה ספרים.\u0004","\u0003כתב אות אחת ומחק\u0004 אותה \u0003אות אחת\u0004 במים, \u0003וכתב אות אחת\u0004 נוספת \u0003ומחק\u0004 אותה \u0003אות אחת —\u0004 \u0003פסולה, דכתיב\u0004 \u0003[שנאמר]:\u0004 \u0003\"ועשה לה הכהן את כל התורה הזאת\"\u0004 (במדבר ה, ל), כלומר, צריכה כל הפרשה להיות כתובה ולהימחק יחד, בשלימות.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: כתב שתי מגילות לשתי סוטות, ומחקן לתוך כוס אחד מהו?\u0004 האם \u0003כתיבה לשמה\u0004 (לשם אשה מסויימת) \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003והאיכא\u0004 \u0005[והרי יש\u0006 כאן\u0005],\u0006 שהרי כתב מגילה לכל אחת בנפרד — וכשרים המים להשקאת שתיהן \u0003או דילמא בעינן נמי\u0004 \u0005[שמא צריכים אנו גם כן]\u0006 שתהא \u0003מחיקה לשמה,\u0004 וכיון שמחקן ביחד אין כאן מחיקה לשם כל אשה בנפרד — ופסולים הם?","\u0003ואם תמצא לומר\u0004 כי \u0003בעינן נמי\u0004 \u0005[צריכים אנו גם כן]\u0006 שתהא \u0003מחיקה לשמה,\u0004 אם \u0003מחקן בשתי כוסות, וחזר ועירבן\u0004 את המים שבכוסות לאחר מכן \u0003מהו?\u0004 האם רק \u0003מחיקה לשמה בעינן\u0004 \u0005[צריכים אנו],\u0006 \u0003והאיכא\u0004 \u0005[והרי יש\u0006 כאן\u0005],\u0006 שהרי נמחקה כל אחת לשמה, \u0003או דילמא הא לאו דידה קא שתיא והא לאו דידה קא שתיא\u0004 \u0005[שמא זו לא\u0006 את \u0005שלה\u0006 היא \u0005שותה וזו לא\u0006 את \u0005שלה\u0006 היא \u0005שותה]?\u0006","\u0003ו\u0004עוד, \u0003אם תמצא לומר הא לאו דידה קא שתיא והא לאו דידה קא שתיא\u0004 \u0005[זו לא שלה\u0006 היא \u0005שותה וזו לא שלה\u0006 היא \u0005שותה],\u0006 \u0003אם\u0004 \u0003חזר וחלקן\u0004 את המים המאררים ונתן לכל סוטה כוס לעצמה \u0003מהו?\u0004 האם אומרים ש\u0003יש ברירה,\u0004 ונאמר שהתברר הדבר למפרע שכל אחת שותה את שלה, \u0003או אין ברירה?\u0004 לשאלות אלה לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד,\u0006 יעמדו\u0005]\u0006 במקומן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: השקה\u0004 את הסוטה \u0003בסיב,\u0004 כלומר, דרך סיב דקל \u0003מהו,\u0004 או אם השקה \u0003בשפופרת מהו?\u0004 והשאלה היא: האם \u0003דרך שתיה בכך, או אין דרך שתיה בכך?\u0004 אף שאלות אלה לא נמצא להן פתרון ולכן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: נשפכו מהן,\u0004 מן המים, \u0003ונשתיירו מהן מהו?\u0004 האם צריכה לשתות את כל המים שנמחקה המגילה בהם, או די אפילו בחלקם, ואף שאלה זו לא נמצא לה פתרון ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר ר' זירא אמר רב: שתי שבועות האמורות בסוטה\u0004 (\"והשביע אותה הכהן\". \u0005במדבר ה, יט\u0006. \"והשביע הכהן את האשה. \u0005במדבר ה, כא)\u0006 \u0003למה?\u0004 — \u0003אחת קודם שנמחקה מגילה, ואחת לאחר שנמחקה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבא:\u0004 הלא \u0003תרוייהו\u0004 \u0005[שתיהן]\u0006 \u0003קודם שנמחקה מגילה כתיבן\u0004 \u0005[\u0006הן \u0005כתובות]\u0006 ומדוע מייחסים זו לזמן זה וזו לזמן אחר? \u0003אלא אמר רבא:\u0004 שתי השבועות הללו שונות בדבר אחר, \u0003אחת\u0004 היא \u0003שבועה שיש עמה אלה\u0004 (קללה), \u0003ואחת\u0004 היא \u0003שבועה שאין עמה אלה.\u0004","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד היא]\u0006 \u0003שבועה שיש עמה אלה? אמר רב עמרם אמר רב:\u0004 כגון שאומר: \u0003\"משביעני עליך שלא נטמאת, שאם נטמאת —\u0004 \u0003יבואו ביך\u0004 (בך) כל הקללות הללו\u0003\".\u0004","\u0003אמר רבא:\u0004 והרי אם אומר כך \u0003אלה לחודה קיימא\u0004 \u0005[לעצמה עומדת]\u0006 \u0003ושבועה לחודא קיימא\u0004 \u0005[לעצמה עומדת]\u0006 ואין זה נחשב לשבועת האלה, שהרי אמר לה את האלה במשפט לעצמו! \u0003אלא אמר רבא,\u0004 כך הלשון: \u0003\"משביעני עליך שאם נטמאת יבואו ביך\".\u0004","\u0003אמר רב אשי:\u0004 במקרה זה \u0003אלה —\u0004 \u0003איכא\u0004 \u0005[יש\u0006 כאן\u0005]\u0006 אבל \u0003שבועה\u0004 שלא נטמאת — \u0003ליכא\u0004 \u0005[אין]!\u0006 \u0003אלא אמר רב אשי,\u0004 כך הנוסח: \u0003משביעני עליך שלא נטמאת, ואם נטמאת יבואו ביך,\u0004 שהשבועה היא גם שתחול האלה.","\u0003על מה היא אומרת \"אמן אמן\"\u0004 שתי פעמים — \u0003אמן על האלה\u0004 שהיא מקבלת על עצמה את הקללה, \u0003אמן על השבועה\u0004 שמשביע אותה שטהורה היא, \u0003אמן\u0004 אם זנתה \u0003מאיש זה\u0004 שנחשדה בו, \u0003אמן מאיש אחר. אמן שלא שטיתי\u0004 לא רק עכשיו, אלא גם בהיותי \u0003ארוסה ונשואה\u0004"],["\u0003ושומרת יבם\u0004 שמת בעלה בלי בנים, והיא ממתינה (\"שומרת\") ליבם שישאנה או יחלוץ לה, \u0003וכנוסה\u0004 לאחר שנתייבמה. \u0003אמן שלא נטמאתי, ואם נטמאתי —\u0004 \u0003יבואו\u0004 (יתקיימו) \u0003בי\u0004 כל הקללות הללו.","\u0003ר' מאיר אומר:\u0004 \"אמן אמן\" פירושו — \u0003אמן שלא נטמאתי\u0004 בעבר, \u0003אמן שלא אטמא\u0004 בעתיד.","\u0003הכל שוין שאין מתנה עמה\u0004 בהשבעה זו \u0003לא על\u0004 מה שעשתה \u0003קודם שתתארס\u0004 (שהתארסה) לו, \u0003ולא על\u0004 מה שתעשה \u0003אחר שתתגרש\u0004 ממנו.","וכן אשה שגירשה בעלה ובהיותה גרושה \u0003נסתרה לאחד ונטמאת, ואחר כך החזירה\u0004 בעלה וקינא לה ונסתרה ובא להשקותה מי סוטה — \u0003לא היה מתנה עמה\u0004 שתישבע שלא נטמאה מזמן שגירשה, לפי שבהיותה גרושה אינה נאסרת עליו אם נבעלה בזנות.","\u0003זה הכלל:\u0004 על \u0003כל\u0004 מקרה \u0003שתבעל\u0004 לאחר \u0003ולא היתה אסורה לו\u0004 על ידי בעילה זו — \u0003לא היה מתנה עמה.\u0004 ובשבועה יכול לכלול רק דברים שאם עושה אותם נאסרת עליו.","\u0003אמר רב המנונא: שומרת יבם שזינתה —\u0004 \u0003אסורה ליבמה. ממאי\u0004 \u0005[ממה]\u0006 למד הוא זאת — \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 במשנתנו \u0003\"שומרת יבם וכנוסה\".\u0004","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ששומרת יבם שזינתה \u0003אסירה\u0004 \u0005[אסורה]\u0006 עליו — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003מתנה בהדא\u0004 \u0005[עימה],\u0006 ומשביעה שלא זינתה אז, \u0003אלא אי אמרת לא אסירה\u0004 \u0005[אם אומר אתה\u0006 ש\u0005אינה אסורה] —\u0006 \u0003היכי\u0004 \u0005[איך]\u0006 \u0003מתנה בהדה\u0004 \u0005[עימה]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003זה הכלל: כל שאילו תיבעל ולא תהא אסורה לו —\u0004 \u0003לא היה מתנה עמה!\u0004","\u0003אמרי במערבא\u0004 \u0005[אומרים בארץ ישראל]:\u0006 \u0003לית הילכתא\u0004 \u0005[אין הלכה]\u0006 \u0003כרב המנונא\u0004 לגבי שומרת יבם.","ו\u0003אלא הא דקתני\u0004 \u0005[זו ששנה]\u0006 במשנתנו \u0003\"שומרת יבם וכנוסה\"\u0004 — אין ללמוד מכאן, ומדוע, כי \u0003הא מני\u0004 \u0005[זו,\u0006 משנתנו, כדעת \u0005מי היא]\u0006 כדעת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: אין קדושין תופסין בחייבי לאוין, ומשוי לה כי\u0004 \u0005[מחשיב אותה כמו]\u0006 \u0003ערוה,\u0004 שהרי שומרת יבם הנבעלת לאחר עוברת על לאו, ולשיטתו אין הבדל בין איסורי לאו ואיסורי כרת ונאסרת על היבם.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' ירמיה: מהו שיתנה אדם\u0004 עם אשתו שנסתרה, \u0003על נישואין הראשונים\u0004 שהיתה נשואה לו פעם וגירשה והחזירה, שלא זינתה גם אז, וכן \u0003על נישואי אחיו\u0004 שמת בלי בנים והוא ייבם את אשתו, \u0003מהו?\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003זה הכלל, כל שתיבעל ולא תהא אסורה לו\u0004 בבעילה זו — \u0003לא היה מתנה עמה. הא אסירה\u0004 \u0005[הרי\u0006 אם היתה \u0005אסורה]\u0006 על ידי בעילה זו — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 ש\u0003מתנה,\u0004 וכן בשני המקרים הללו, כיון שאם זינתה היתה נאסרת עליו, יכול להשביעה. ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא ורשאי להתנות במקרה כזה.","שנינו במשנה במשמעות \"אמן אמן\" שאומרת האשה, ש \u0003ר' מאיר אומר: אמן שלא נטמאתי,\u0004 אמן שלא אטמא. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003לא כשאמר ר' מאיר אמן שלא אטמא\u0004 התכוון לומר \u0003שאם תטמא\u0004 בעתיד \u0003מים\u0004 ששותה כעת \u0003בודקין אותה\u0004 כבר \u0003מעכשיו,\u0004 \u0003אלא\u0004 הכוונה היא \u0003לכשתטמא\u0004 בעתיד — \u0003מים\u0004 ששותה כעת \u0003מערערין אותה ובודקין אותה\u0004 אז.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רב אשי: מהו שיתנה אדם\u0004 בשעה שמשקה את אשתו \u0003על נישואין האחרונים?\u0004 כלומר, שאם יגרשנה ויחזירנה, שלא תיטמא לאחר באותם נישואין אחרונים. האם נאמר: \u0003השתא מיהא לא אסירה ליה\u0004 \u0005[עכשיו על כל פנים אינה אסורה לו],\u0006 שהרי לגבי הנישואין הראשונים היא טהורה, \u0003או דילמא זימנין דמגרש לה והדר מהדר לה\u0004 \u0005[שמא פעמים ש\u0006הוא \u0005מגרש אותה\u0006 ו\u0005חוזר ומחזיר אותה]\u0006 ותיאסר אז עליו, ומשום כך יכול הוא להשביעה עכשיו?","ועונים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנתנו: \u0003הכל שוין שלא היה מתנה עמה לא על קודם שתתארס, ולא על אחר שתתגרש.\u0004 ומדייקים: דווקא \u0003נסתרה לאחד ונטמאת\u0004 לאחר שגירשה \u0003ואחר כך יחזירנה —\u0004 \u0003לא היה מתנה,\u0004 שבשעה שנסתרה לא היתה אשתו ולא נאסרה עליו, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יחזירנה ותיטמא\u0004 — תיאסר עליו. \u0003הכי נמי דמתני\u0004 \u0005[כך גם כן ש\u0006הוא \u0005מתנה]\u0006 כבר מעכשיו. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר \u0003\"זאת תורת הקנאת\"\u0004 (במדבר ה, כט) בלשון רבים, \u0003מלמד שהאשה שותה ושונה,\u0004 כלומר, חוזרת ושותה פעם אחרת.","\u0003ר' יהודה אומר\u0004 להיפך: \u0003\"זאת\"\u0004 הוא לשון מיעוט, \u0003שאין האשה שותה ושונה. אמר ר' יהודה: מעשה והעיד לפנינו נחוניא חופר שיחין\u0004 שקיבל מרבותיו \u0003שהאשה שותה ושונה, וקיבלנו עדותו בשני אנשים,\u0004 שאם היתה נשואה לשנים יכול להיות ששותה ושונה אצל בעלה השני, \u0003אבל לא באיש אחד.\u0004","\u0003וחכמים אומרים: אין האשה שותה ושונה, בין באיש אחד בין בשני אנשים.\u0004","ושואלים: \u0003ו\u0004לדעת ה\u0003תנא קמא נמי\u0004 \u0005[הראשון, גם כן]\u0006 \u0003הכתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"זאת\"\u0004 למעט! ולהיפך, \u0003ורבנן בתראי נמי\u0004 \u0005[ו\u0006לדעת \u0005חכמים אחרונים\u0006 שנזכרו בברייתא, \u0005גם כן]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"תורת\u0004 הקנאות\" בלשון רבים!","\u0003אמר רבא: באיש אחד\u0004 שחשד באשתו \u0003ובועל אחד —\u0004 \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003אין האשה שותה ושונה,\u0004 אם קינא לה שנית מאותו אדם ונסתרה עימו שנית,"],["\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"זאת\"\u0004 (במדבר ה, כט) שהוא לשון מיעוט. \u0003בשני אנשים\u0004 (בעלים) שונים של אותה אשה שחשדו בה, \u0003ושני בועלין\u0004 שונים, שקינא לה בעלה הראשון מאדם אחד ובעלה השני מאדם אחר — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 ש\u0003האשה שותה ושונה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"תורת\u0004 הקנאות \u0003\"\u0004(שם) בלשון רבים. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003באיש אחד ושני בועלין,\u0004 שקינא לה בעלה כל פעם מאדם אחר, או \u0003בשני אנשים\u0004 (בעלים) \u0003ובועל אחד;\u0004 \u0003תנא קמא\u0004 \u0005[התנא הראשון]\u0006 \u0003סבר: \"תורת\u0004 הקנאות \u0003\"\u0004בא \u0003לרבויי כולהי\u0004 \u0005[לרבות\u0006 את \u0005כולם]\u0006 שבכל אופן שותה ושונה, \u0003\"זאת\"\u0004 בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 רק \u0003איש אחד ובועל אחד.\u0004","","","\u0003ורבנן בתראי סברי\u0004 \u0005[וחכמים אחרונים סבורים]:\u0006 \u0003\"זאת\"\u0004 בא \u0003למעוטי כולהי\u0004 \u0005[למעט\u0006 את \u0005כולם],\u0006 \u0003\"תורת\u0004 הקנאות\" בא \u0003לרבויי\u0004 \u0005[לרבות]\u0006 רק \u0003שני אנשים ושני בועלין.\u0004","\u0003ור' יהודה\u0004 סבור: \u0003\"זאת\"\u0004 בא \u0003למעוטי תרתי\u0004 \u0005[למעט שנים]\u0006 מן המקרים, \u0003\"תורת\" לרבות תרתי\u0004 \u0005[שנים].\u0006 ומפרטים: \u0003\"זאת\" למעוטי תרתי\u0004 \u0005[למעט שנים]\u0006 — \u0003איש אחד ובועל אחד\u0004 ואפילו \u0003איש אחד ושני בועלין, \"תורת\u0004 הקנאות \u0003\"\u0004בא \u0003לרבויי תרתי\u0004 \u0005[לרבות שנים],\u0006 בין \u0003שני אנשים ובועל אחד,\u0004 וכל שכן \u0003שני אנשים ושני בועלין.\u0004","","\u0003היה נוטל את מנחתה מתוך כפיפה מצרית\u0004 (סל העשוי מעלי דקל) שהיא מונחת בה, \u0003ונותנה לתוך כלי שרת, ונותנה על ידה, וכהן מניח ידו מתחתיה ומניפה. הניף\u0004 הכהן, \u0003והגיש\u0004 את המנחה למזבח, \u0003קמץ\u0004 ממנה, \u0003והקטיר\u0004 את הקומץ, \u0003והשאר נאכל לכהנים.\u0004","ובסדר הדברים: \u0003היה משקה\u0004 את האשה \u0003ואחר כך מקריב את מנחתה. ר' שמעון אומר: מקריב את מנחתה ואחר כך היה משקה, שנאמר:\u0004 \"וקמץ הכהן מן המנחה... והקטיר המזבחה \u0003ואחר ישקה את האשה את המים\"\u0004 (במדבר ה, כו). אמנם מודה ר' שמעון שגם \u0003אם השקה ואחר כך הקריב את מנחתה\u0004 הרי היא \u0003כשרה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר לר' יאשיה דדריה\u0004 \u0005[של,\u0006 בן, \u0005דורו]\u0006 (להבדילו מר' יאשיה התנא, שהיה גדול מר' אלעזר): \u0003לא תיתב אכרעך\u0004 \u0005[תשב על רגליך]\u0006 \u0003עד דמפרשת לה להא מילתא\u0004 \u0005[שאתה מפרש אותה\u0006 לי, \u0005את הדבר הזה]:\u0006 \u0003מנין למנחת סוטה שטעונה תנופה?\u0004 ותוהים על השאלה: \u0003מנא לן\u0004 \u0005[מניין לנו]?!\u0006 הלא \"ולקח הכהן מיד האשה את מנחת הקנאות \u0003והניף\u0004 את המנחה לפני ה'\" (במדבר ה, כה) \u0003כתיב\u0004 \u0005[כתוב]\u0006 \u0003בה\u0004 במפורש! אלא השאלה היתה: תנופה שצריכה שתיעשה \u0003בבעלים,\u0004 כלומר, באשה \u0003מנלן\u0004 \u0005[מניין לנו]?\u0006","השיב לו ר' יאשיה: \u0003אתיא\u0004 \u0005[באה,\u0006 נלמדת\u0005]\u0006 ההלכה בגזירה שווה \u0003\"יד\" \"יד\" מ\u0004קרבן \u0003שלמים; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 בסוטה: \u0003\"ולקח הכהן מיד האשה\"\u0004 (במדבר ה, כה), \u0003וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בשלמים: \"המקריב את זבח שלמיו לה'... \u0003ידיו תביאינה\u0004 את אשי ה'... להניף אותו תנופה לפני ה\"' (ויקרא ז, כט-ל),","\u0003מה כאן\u0004 בסוטה \u0003כהן\u0004 מניף גם כן — \u0003אף להלן\u0004 בשלמים מניף גם ה\u0003כהן, ומה להלן\u0004 בשלמים מניפים גם ה\u0003בעלים אף כאן\u0004 בסוטה מניפים גם ה\u0003בעלים. הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 מקיימים את שני הכתובים כאחד? — \u0003מניח\u0004 הכהן \u0003ידו תחת ידי הבעלים ומניף.\u0004","שנינו במשנה: \u0003הניף והגיש קמץ\u0004 והקטיר, ואחר כך שנינו: \u0003היה משקה ואחר כך מקריב את מנחתה.\u0004 ותוהים: \u0003הא אקרבה\u0004 \u0005[הרי הקריב אותה]\u0006 כבר, לפי האמור בסדר זה שבמשנה!","אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003סדר מנחות\u0004 בדרך כלל \u0003כיצד? הניף והגיש, קמץ והקטיר, והשאר נאכל לכהנים.\u0004 \u0003ו\u0004אולם \u0003בהשקאה\u0004 של סוטה \u0003גופה\u0004 \u0005[עצמה]\u0006 \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003ר' שמעון ורבנן\u0004 \u0005[וחכמים];\u0006 \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003משקה ואחר כך מקריב את מנחתה, ו\u0004אילו \u0003ר' שמעון סבר\u0004 \u0005[סבור]:\u0006 \u0003מקריב את מנחתה ואחר כך משקה, שנאמר:\u0004 \u0003\"ואחר ישקה\"\u0004 (במדבר ה, כו). \u0003ו\u0004עוד נאמר במשנה שאף לדברי ר' שמעון \u0003אם השקה ואחר כך הקריב את מנחתה —\u0004 \u0003כשרה.\u0004","",""],["\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \u0003\"והשקה\u0004 את המים\u0003\"\u0004 (במדבר ה, כז) ויש לשאול: \u0003מה תלמוד לומר\u0004 פעם שנית? \u0003והלא כבר נאמר \"והשקה\u0004 את האשה את מי המרים\u0003\"\u0004 (במדבר ה, כד)! אלא בא הדבר ללמד \u0003שאם נמחקה\u0004 כבר ה\u0003מגילה ו\u0004אז \u0003אומרת\u0004 האשה \u0003\"איני שותה\" —\u0004 \u0003מערערין\u0004 (כופים) \u0003אותה, ומשקין אותה בעל כרחה,\u0004 אלו \u0003דברי ר' עקיבא.\u0004","\u0003ר' שמעון אומר:\u0004 זה שנאמר \u0003\"ואחר ישקה\u0004 את האשה\u0003\"\u0004 (במדבר ה, כו), \u0003מה תלמוד לומר? והלא כבר נאמר \"והשקה\"\u0004 (במדבר ה, כד)! \u0003אלא\u0004 בא כתוב זה לומר לנו כי רק ל\u0003אחר כל מעשים כולן האמורין למעלה\u0004 (של מחיקת המגילה והקרבת המנחה והשבעתה) משקה אותה. \u0003מגיד\u0004 הכתוב ש\u0003שלשה דברים מעכבין בה\u0004 בסוטה, מלשתות: \u0003עד שלא קרב הקומץ\u0004 אינה שותה, \u0003ועד שלא נמחקה מגילה\u0004 אינה שותה, \u0003ועד שלא תקבל עליה שבועה\u0004 אינה שותה.","ומעירים: \u0003עד שלא קרב הקומץ —\u0004 \u0003ר' שמעון לטעמיה,\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: מקריב את מנחתה ואחר כך משקה.\u0004","על האמור שם \u0003עד שלא נמחקה מגילה\u0004 אינה שותה, תוהים: מה צורך לומר כן, \u0003אלא מאי\u0004 \u0005[מה]\u0006 \u0003משקה לה\u0004 \u0005[אותה]\u0006 אם עדיין לא נמחקה המגילה בתוך המים? \u0003אמר רב אשי: לא נצרכה\u0004 הלכה זו אלא \u0003לשרישומו ניכר,\u0004 כלומר, כאשר המגילה עדיין לא נמחקה לגמרי ורישומו של הכתב על הקלף עוד ניכר.","על האמור שאינה שותה \u0003עד שלא תקבל עליה שבועה,\u0004 מעירים, נדייק מכאן: \u0003מישתא\u0004 \u0005[לשתות]\u0006 \u0003הוא\u0004 ש\u0003לא שתיא\u0004 \u0005[שותה]\u0006 \u0003הא מיכתב כתבי\u0004 \u0005[הרי\u0006 ש\u0005כותבים]\u0006 \u0003לה\u0004 את המגילה, \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: מגילת סוטה שכתבה קודם שתקבל עליה שבועה —\u0004 \u0003לא עשה ולא כלום!\u0004 ומשיבים: \u0003כדי נסבה\u0004 \u0005[לחינם הביא אותה].\u0006 כלומר, דבר זה שאין יכולה לשתות לפני קבלת שבועה לחינם נאמר, שהרי ודאי עוד לא נכתבה מגילה ולא נמחקה.","ושואלים: תנאים אלה שבמשנתנו \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]?\u0006 ומשיבים: \u0003תלתא קראי כתיבי\u0004 \u0005[שלושה כתובים נאמרו]:\u0006 \u0003\"והשקה\" קמא\u0004 \u0005[ראשון]\u0006 (במדבר ה, כד), \u0003\"ואחר ישקה\"\u0004 (במדבר ה, כו), \u0003\"והשקה\" בתרא\u0004 \u0005[אחרון]\u0006 (במדבר ה, כז).","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003\"והשקה\" קמא\u0004 \u0005[הראשון]\u0006 \u0003לגופו,\u0004 שכך צריך לעשות לפי סדר זה \u0003שמשקה ואחר כך מקריב את מנחתה,\u0004 \u0003\"ואחר ישקה\" מיבעי ליה\u0004 \u0005[צריך לו]\u0006 \u0003ל\u0004למד \u0003ש\u0004אם \u0003רישומו\u0004 של הכתב \u0003ניכר\u0004 שאין משקים, \u0003\"והשקה\" בתרא\u0004 \u0005[אחרון]\u0006 ללמד \u0003שאם נמחקה מגילה ואומרת \"איני שותה\" —\u0004 \u0003מערערין אותה ומשקה אותה בעל כרחה.\u0004","\u0003ור' שמעון סבר: \"ואחר ישקה\" —\u0004 \u0003לגופו\u0004 בא, ללמדנו סדר הדברים \u0003שמקריב את מנחתה ואחר כך משקה, \"והשקה\" קמא\u0004 \u0005[הראשון]\u0006 בא לומר \u0003שאם השקה ואחר כך הקריב את מנחתה\u0004 — בכל זאת \u0003כשרה, \"והשקה\" בתרא\u0004 \u0005[האחרון]\u0006 — \u0003שאם נמחקה מגילה ואמרה \"איני שותה\" מערערין אותה ומשקין אותה בעל כרחה.\u0004","ומסבירים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים ש\u0003בדיעבד לא פתח קרא\u0004 \u0005[הכתוב]\u0006 שאין הכתוב פותח מתחילה בציווי מה לעשות כאשר לא נעשו הדברים כראוי, לפיכך אין הם מפרשים כר' שמעון ש\"והשקה\" הראשון בא ללמד שאם השקה ואחר כך הקריב — כשר בדיעבד.","ושואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' עקיבא\u0004 ש\u0003משקין אותה בעל כרחה? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה אומר: כלבוס\u0004 (כעין וו) \u0003של ברזל מטילין\u0004 (מכניסים בכוח) \u0003לתוך פיה, שאם נמחקה מגילה ואמרה \"איני שותה\" —\u0004 \u0003מערערין אותה\u0004 באמצעותו \u0003ומשקין אותה בעל כרחה. אמר ר' עקיבא: כלום אנו צריכין\u0004 להשקות מי סוטה \u0003אלא\u0004 כדי \u0003לבודקה\u0004 אם טמאה היא, \u0003והלא\u0004 זו \u0003בדוקה ועומדת,\u0004 שכיון שאומרת שאינה שותה הרי היא כמודה שהיא טמאה! \u0003אלא\u0004 כך צריך לומר: \u0003עד שלא קרב הקומץ יכולה לחזור בה\u0004 ולומר \"איני שותה\", \u0003משקרב הקומץ אינה יכולה לחזור בה.\u0004 ולדעתו, בכל אופן שהוא אין משקים אותה בעל כרחה!","ושואלים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שר' עקיבא אכן סבור כך, \u0003תיקשי\u0004 \u0005[תיקשה]\u0006 \u0003לך היא גופה\u0004 \u0005[עצמה]\u0006 העמדה זאת של הדברים: מדוע \u0003משקרב הקומץ אינה יכולה לחזור בה? והלא בדוקה ועומדת,\u0004 שהרי היא כמודה שהיא טמאה!","אלא ודאי \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שמשקים אותה בעל כרחה — הרי זה באופן \u0003דקהדרא\u0004 \u0005[שחוזרת]\u0006 \u0003בה מחמת רתיתא\u0004 \u0005[פחד],\u0006 שיש לחשוש שמא טהורה היא ורק פחד הוא שאחז בה, ואם תיבדק תימצא טהורה, \u0003והא\u0004 \u0005[וזו]\u0006 שאמרנו שאין משקים אותה — הרי זה באופן \u0003דקהדרא\u0004 \u0005[שחוזרת]\u0006 \u0003בה מחמת בריותא\u0004 \u0005[בריאות],\u0006 שהרי היא כמודה שנטמאה, ואין כאן סתירה בדברי ר' עקיבא.","\u0003והכי קאמר\u0004 \u0005[וכך אמר]:\u0006 \u0003כל\u0004 שחוזרת בה \u0003מחמת בריותא\u0004 \u0005[\u0006שהיא ב\u0005בריאות],\u0006 כשהיא בכוחה — \u0003כלל כלל לא שתיא\u0004 \u0005[שותה],\u0006 שהרי היא כמודה שנטמאה. והחוזרת בה \u0003מחמת רתיתא\u0004 \u0005[פחד];\u0006 תלוי אם \u0003עד שלא קרב הקומץ, דאכתי\u0004 \u0005[שעדיין]\u0006 \u0003לא אמחוק\u0004 \u0005[נמחקה]\u0006 ה\u0003מגילה, אי נמי אמחוק\u0004 \u0005[או גם כן נמחקה]\u0006 כבר \u0003מגילה,\u0004 שבמקרה זה \u0003שלא כדין עביד\u0004 \u0005[עשו]\u0006 \u0003כהנים דמחקי\u0004 \u0005[שמחקו\u0006 אותה\u0005]\u0006 לפני כן — \u0003מצי הדרא\u0004 \u0005[יכולה\u0006 היא \u0005לחזור]\u0006 \u0003בה. משקרב הקומץ,\u0004 ש\u0003בדין עביד\u0004 \u0005[עשו]\u0006 \u0003כהנים דמחקי\u0004 \u0005[שמחקו]\u0006 את המגילה — הריהי \u0003לא מצי הדרא\u0004 \u0005[יכולה לחזור]\u0006 \u0003בה,\u0004 ומשקים אותה בעל כרחה."],["\u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' עקיבא אדר'\u0004 \u0005[על\u0006 דברי \u0005ר']\u0006 \u0003עקיבא: התם\u0004 \u0005[שם]\u0006 \u0003אמר\u0004 ש\u0003מחיקה מעכבא\u0004 \u0005[מעכבת],\u0006 שאם לא נמחקה המגילה, אין משקים אותה בעל כרחה, \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003אמר קומץ מעכב,\u0004 שאם עדיין לא קרב, על אף שכבר נמחקה המגילה, אין משקים אותה בעל כרחה!","ומשיבים: \u0003תרי תנאי ואליבא\u0004 \u0005[שני תנאים\u0006 חלוקים בכך \u0005ועל פי שיטתו]\u0006 של \u0003ר' עקיבא.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003אמרה \"איני שותה\"\u0004 תחילה \u0003מחמת בריותא\u0004 \u0005[\u0006שהיתה ב\u0005בריאות]\u0006 ובכוחה, \u0003וחזרה ואמרה \"שותה אני\", מהו?\u0004 האם נאמר \u0003כיון\u0004 ש\u0003אמרה איני שותה\"\u0004 — כאילו \u0003\"טמאה אני\" קאמרה\u0004 \u0005[היא אומרת],\u0006 שבכך הודתה שהיא טמאה, \u0003וכיון דאחזיק\u0004 \u0005[שהחזיקה]\u0006 \u0003נפשה,\u0004 את עצמה, \u0003בטומאה לא מציא הדרה\u0004 \u0005[אינה יכולה לחזור]\u0006 \u0003בה, או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 ש\u0003אמרה\u0004 אחר כך \u0003\"שותה אני\" גליא\u0004 \u0005[גילתה]\u0006 בכך \u0003דעתה\u0004 ש\u0003מחמת ביעתותא\u0004 \u0005[פחד]\u0006 \u0003הוא\u0004 ש\u0003אמרה\u0004 תחילה שאינה שותה ויכולה לחזור בה ולשתות? לשאלה זו לא נמצאה תשובה, ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003אמר אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל: צריך שיתן\u0004 דבר \u0003מר לתוך המים\u0004 ששותה הסוטה. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ומחה אל \u0003מי המרים\"\u0004 (במדבר ה, כג), לומר \u0003שמרים\u0004 היו \u0003כבר\u0004 לפני שמחקו את המגילה.","אם \u0003עד שלא נמחקה המגילה אמרה \"איני שותה\" —\u0004 \u0003מגילתה\u0004 שכתבו לה \u0003נגנזת, ומנחתה\u0004 נשרפת ו\u0003מתפזרת על הדשן\u0004 (מקום האפר), \u0003ואין מגילתה כשרה להשקות בה סוטה אחרת.\u0004 אם \u0003נמחקה המגילה ו\u0004אחר כך \u0003אמרה \"טמאה אני\" —\u0004 \u0003המים נשפכין, ומנחתה מתפזרת על בית הדשן.\u0004 אם כבר \u0003נמחקה המגילה ואמרה \"איני שותה\" —\u0004 \u0003מערערין\u0004 (מכריחים) \u0003אותה, ומשקין אותה בעל כרחה.\u0004","ומוסיפים: אם אכן היתה טמאה \u0003אינה מספקת לשתות עד שפניה מוריקות\u0004 (מקבלות צבע ירוק), \u0003ועיניה\u0004 נהיות \u0003בולטות, והיא מתמלאת גידין,\u0004 שגידי הדם שלה בולטים מן הבשר. \u0003והם,\u0004 האנשים העומדים שם, \u0003אומרים: הוציאוה, שלא תטמא\u0004 את \u0003העזרה\u0004 אם תמות מיד שם.","\u0003אם יש לה זכות —\u0004 \u0003היתה תולה לה\u0004 שלא תמות מיד. ומעירים: \u0003יש זכות תולה שנה אחת, יש זכות\u0004 גדולה יותר \u0003תולה שתי שנים, יש זכות תולה שלש שנים. מכאן אומר בן עזאי: חייב אדם ללמד את בתו תורה, שאם תשתה\u0004 ולא תמות מיד \u0003תדע שהזכות תולה לה.\u0004 ואילו \u0003ר' אליעזר אומר: כל המלמד בתו תורה (כאילו) לומדה תפלות\u0004 (זנות).","\u0003ר' יהושע אומר: רוצה אשה בקב\u0004 של מזונות \u0003ותפלות\u0004 עימו, יותר \u0003מתשעה קבין ופרישות. הוא היה אומר: חסיד שוטה, ורשע ערום, ואשה פרושה, ומכות פרושין\u0004 (צבועים העושים עצמם כפרושים) — \u0003הרי אלו מבלי עולם,\u0004 כלומר, מחריבים את העולם.","\u0003אמר רב יהודה אמר שמואל משום ר' מאיר,\u0004 וכך סיפר: \u0003כשהייתי למד תורה אצל ר' עקיבא, הייתי מטיל קנקנתום\u0004 (חומר צביעה) \u0003לתוך הדיו\u0004 שהייתי כותב בו ספרי תורה, \u0003ולא אמר לי דבר\u0004 על כך. \u0003כשבאתי\u0004 אחר כך ללמוד תורה \u0003אצל ר' ישמעאל, אמר לי: בני מה מלאכתך? אמרתי לו: לבלר\u0004 (סופר) \u0003אני,\u0004 כותב ספרי תורה. \u0003אמר לי: בני, הוי זהיר\u0004 במלאכתך, \u0003ש\u0004כן \u0003מלאכתך מלאכת שמים היא, שמא תחסיר אות אחת או תתיר\u0004 (תותיר, תוסיף) \u0003אות אחת\u0004 בספר תורה, ו\u0003נמצאת אתה מחריב את כל העולם כלו\u0004 בשגיאה שהופכת את מובנו של הכתוב, ויכולה להיות דברי חירוף וגידוף.","\u0003אמרתי לו: דבר אחד יש לי שאני מטיל לתוך הדיו, וקנקנתום שמו,\u0004 והוא גורם שלא ימחק הכתב. \u0003אמר לי: וכי מטילין קנקנתום לתוך הדיו?\u0004 הלא \u0003התורה אמרה\u0004 במגילת הסוטה \u0003\"ומחה\"\u0004 (במדבר ה, כג), ומכאן שצריכה התורה להיכתב ב\u0003כתב שיוכל למחות!\u0004","על דו־שיח זה תוהים: \u0003מאי קאמר ליה ומאי קא מהדר ליה\u0004 \u0005[מה אמר לו ומה השיב לו]?\u0006 שלכאורה דברי ר' מאיר אינם תשובה כלל לדבריו של ר' ישמעאל!","ומסבירים: \u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 ר' מאיר: \u0003לא מבעיא\u0004 \u0005[נצרכה]\u0006 לומר \u0003בחסירות ויתירות\u0004 שאינני טועה, ש\u0003בקי אנא\u0004 \u0005[אני],\u0006 \u0003אלא אפילו למיחש\u0004 \u0005[לחשוש]\u0006 \u0003לזבוב דדילמא אתי ויתיב אתגיה דדלי\"ת ומחיק ליה ומשוי ליה רי\"ש\u0004 \u0005[שמא יבוא ויישב על תגו של הדל\"ת וימחק אותו ויעשה אותו רי\"ש]\u0006 שיכול הדבר להיות טעות חמורה, כגון שכותב במקום \"ה' אחד\" — \"ה' אחר\", אף לזה איני חושש, כי \u0003דבר אחד יש לי שאני מטיל לתוך הדיו וקנקנתום שמו,\u0004 שאינו ניתן למחיקה.","ותוהים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]\u0006 הדבר? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' מאיר: כשהייתי למד תורה אצל ר' ישמעאל הייתי מטיל קנקנתום לתוך הדיו, ולא אמר לי דבר. כשבאתי אצל ר' עקיבא אסרה עלי!\u0004","ויש כאן כמה סתירות: \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003שמוש\u0004 על ענין \u0003שמוש,\u0004 שמן הברייתא הראשונה מובן שקודם למד אצל ר' עקיבא ואחר כך אצל ר' ישמעאל, ובברייתא השניה משמע להיפך. ועוד, \u0003קשיא\u0004 \u0005[קשה]\u0006 מענין \u0003אסרה\u0004 על ענין \u0003אסרה,\u0004 שבברייתא הראשונה נאמר שר' ישמעאל אסר כתיבה בדיו עם קנקנתום, ובשניה נאמר שר' עקיבא הוא שאסרה!","ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מענין \u0003שמוש\u0004 על ענין \u0003שמוש לא קשיא\u0004 \u0005[קשה],\u0006 שאפשר לתרץ: \u0003מעיקרא אתא לקמיה\u0004 \u0005[מתחילה בא לפני]\u0006 \u0003ר' עקיבא\u0004 ללמוד, \u0003כיון\u0004 ש\u0003לא מצי קם אליביה\u0004 \u0005[יכול\u0006 היה \u0005לעמוד על שיטתו]\u0006 בלימוד שהיתה מסובכת ביותר \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' ישמעאל וגמר גמרא\u0004 \u0005[ולמד\u0006 את \u0005המסורת],\u0006 \u0003הדר אתא לקמיה\u0004 \u0005[חזר\u0006 ו\u0005בא לפני]\u0006 \u0003ר' עקיבא\u0004 ו\u0003סבר סברא\u0004 (סברה) על פי שיטת ר' עקיבא, להבין את טעמי ההלכה בדברים שלמד כבר.","\u0003אלא אסרה\u0004 על \u0003אסרה קשיא\u0004 \u0005[קשה],\u0006 שיש כאן סתירה! ומשיבים: אכן \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יהודה אומר, אומר היה ר' מאיר: לכל\u0004 כתבי הקודש (ספר תורה תפילין ומזוזות) \u0003מטילין קנקנתום לתוך הדיו\u0004"],["\u0003חוץ מפרשת סוטה\u0004 הכתובה בספר תורה \u0003בלבד. ר' יעקב אומר משמו\u0004 של ר' מאיר: \u0003חוץ מפרשת סוטה של מקדש\u0004 בלבד, כלומר, המגילה הנכתבת במיוחד עבור הסוטה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם],\u0006 כלומר, מה יסוד המחלוקת ביניהם? \u0003אמר ר' ירמיה\u0004 בשאלה האם מותר \u0003למחוק לה\u0004 לסוטה את פרשת סוטה \u0003מן התורה\u0004 מספר תורה \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 מחלוקת, שלדעת ר' מאיר מותר למחוק ולכן בפרשת סוטה הכתובה בספר תורה אין מטילים בה קנקנתום, כדי שתהא ראויה להימחק, ולדעת ר' יעקב אסור למחוק פרשה הכתובה בספר תורה, ולכן אפשר לכותבה בקנקנתום.","\u0003והני תנאי כי הני תנאי\u0004 \u0005[ותנאים אלה\u0006 נחלקו בכך \u0005כתנאים אלה,\u0006 אחרים\u0005]\u0006 שנחלקו באותה בעיה. \u0003דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מגילתה\u0004 של סוטה אחת \u0003כשירה להשקות בה סוטה אחרת.\u0004 משמע שהמגילה צריכה להיכתב לשם הסוטה, ומשום כך אף אין למחוק פרשת סוטה שבספר תורה שהרי לא נכתבה לשם סוטה זו, וכדעת ר' יעקב. \u0003ר' אחי בר יאשיה אומר: מגילתה כשירה להשקות בה סוטה אחרת\u0004 משמע שאינו סבור שצריכה כתיבה לשמה, וממילא ניתן למחוק פרשת סוטה שבספר תורה, וכדעת ר' מאיר.","\u0003אמר רב פפא: דילמא לא היא\u0004 \u0005[שמא אינו כן]\u0006 ואין המחלוקות הללו מקבילות, שאפשר לומר: \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 ה\u0003תנא קמא התם\u0004 \u0005[הראשון שם]\u0006 שאין מוחקים מגילה שנכתבה לצורך סוטה אחת לשם סוטה אחרת, \u0003אלא כיון דאינתיק לשום\u0004 \u0005[שנותקה,\u0006 נקבעה, \u0005לשם]\u0006 \u0003רחל לא הדרא מינתקא לשום\u0004 \u0005[אינה חוזרת\u0006 ו\u0005נקבעת לשם]\u0006 \u0003לאה, אבל\u0004 פרשת סוטה הכתובה ב\u0003תורה, דסתמא כתיבה הכי נמי דמחקינן\u0004 \u0005[שסתם\u0006 היא \u0005כתובה, כך גם כן\u0006 אפשר לומר \u0005שמוחקים]\u0006 אף שלא נכתבה לשם אשה זאת.","\u0003אמר רב נחמן בר יצחק:\u0004 אפשר לדחות את ההשוואה גם מצד אחר, \u0003דילמא לא היא\u0004 \u0005[שמא אינו כן],\u0006 כי \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' אחי בר יאשיה התם\u0004 \u0005[שם]\u0006 שמוחקים מגילה שנכתבה לשם אשה אחרת \u0003אלא במגילה, דאיכתוב\u0004 \u0005[שנכתבה]\u0006 על כל פנים \u0003לשום\u0004 (לשם) \u0003אלות בעולם\u0004 (בכלל, כל שהן), שהרי מגילה זו נכתבה לשם סוטה. \u0003אבל תורה,\u0004 ש\u0003להתלמד,\u0004 ללמוד ממנה \u0003כתיבה\u0004 \u0005[נכתבה],\u0006 \u0003הכי נמי דלא מחקינן\u0004 \u0005[כך גם כן שאין אנו מוחקים].\u0006","ותמהים: \u0003ור' אחי בר יאשיה\u0004 האם \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו מקבל\u0005]\u0006 הלכה זו שאם \u0003כתב\u0004 אדם \u0003לגרש את אשתו ונמלך\u0004 ולא גירשה, \u0003מצאו בן עירו ואמר לו: שמי כשמך, ושם אשתי כשם אשתך,\u0004 תן לי את הגט ואשתמש בו — \u0003פסול\u0004 גט זה \u0003לגרש בו\u0004 אשה אחרת, שהוא הדין למגילת סוטה?","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בדחיה: \u0003התם\u0004 \u0005[שם]\u0006 בגט \u0003\"וכתב לה\u0004 ספר כריתות\u0003\"\u0004 (דברים כד, א) \u0003אמר רחמנא\u0004 \u0005[אמרה תורה],\u0006 ללמד כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהא \u0003כתיבה לשמה\u0004 של אותה אשה, מה שאין כן בסוטה. ותוהים: \u0003הכא נמי\u0004 \u0005[כאן\u0006 בסוטה \u0005גם כן]\u0006 הרי נאמר \u0003\"ועשה לה\"\u0004 (במדבר ה, ל), ויש לדרוש איפוא גם כאן: \"לה\" — לשמה! ודוחים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"עשייה\"\u0004 האמורה כאן — \u0003מחיקה,\u0004 שזו בודאי צריכה להיות לשמה של אותה אשה, אבל הכתיבה אינה צריכה להיות דווקא לשמה.","שנינו במשנה: \u0003אינה מספקת לשתות עד שפניה\u0004 מוריקים וכו' ומסבירים: \u0003מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]\u0006 משנה זו אשר לפיה כבר בזמן השתיה בודקים אותה המים — כשיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר: מקריב את מנחתה ואחר כך משקה.\u0004 שאילו לשיטת התנא הסבור שמשקה ואחר כך מקריב מנחתה לא היו המים בודקים אותה מיד, שהרי \u0003כמה\u0004 (כל עוד) ש\u0003לא קרבה מנחתה לא בדקי לה מיא\u0004 \u0005[אין המים בודקים אותה]\u0006, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מנחת זכרון מזכרת עון\"\u0004 (במדבר ה, \u0003טו), כלומר, המנחה היא המזכירה את העוון. ומקשים:\u0004","\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003יש לה זכות —\u0004 \u0003היתה תולה לה,\u0004 ואם כן \u0003אתאן\u0004 \u0005[באנו]\u0006 \u0003ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006, \u0003דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' שמעון —\u0004 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003אין זכות תולה במים המרים!\u0004","\u0003אמר רב חסדא: הא מני\u0004 \u0005[זו,\u0006 משנתנו, כדעת \u0005מי היא]\u0006 — כדעת \u0003ר' עקיבא היא,\u0004 ש\u0003אמר: מקריב את מנחתה ואחר כך משקה,\u0004 שבענין זה סבור כר' שמעון \u0003וב\u0004ענין \u0003זכות\u0004 תולה \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004דעת \u0003רבנן.\u0004","\u0003ב שנינו:\u0004 \u0003והם,\u0004 האנשים העומדים שם, \u0003אומרים הוציאוה\u0004 שמא תטמא את העזרה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003דדילמא מתה\u0004 \u0005[ששמא תמות]\u0006 בו במקום ותיטמא העזרה. ותוהים: \u0003למימרא\u0004 \u0005[האם לומר,\u0006 ללמוד מכאן\u0005]\u0006 ש\u0003מת אסור\u0004 להיות \u0003במחנה לויה?\u0004","שעזרת הנשים ששם היו משקים אותה, והר הבית, הם כנגד מחנה הלויים במדבר, \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003טמא מת מותר ליכנס למחנה לויה. ולא טמא מת בלבד אמרו אלא אפילו מת עצמו, שנאמר:\u0004 \u0003\"ויקח משה את עצמות יוסף עמו\"\u0004 (שמות יג, יט) והכוונה היא \u0003עמו —\u0004 \u0003במחיצתו,\u0004 והרי משה היה במחנה לוייה!","\u0003אמר אביי:\u0004 לא לטומאת מיתה אנו חוששים, אלא \u0003שמא\u0004 מהפחד מהמים \u0003תפרוס נדה\u0004 ותטמא בכך את העזרה, שאסור לנידה להכנס למחנה לויה. ושואלים: \u0003למימרא דבעיתותא מרפיא\u0004 \u0005[\u0006האם \u0005לומר שאימה\u0006 גורמת \u0005להרפיה]\u0006 ולשתיתת דם? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ותתחלחל המלכה מאד\"\u0004 (אסתר ד, ד) \u0003ואמר רב: שפירסה נדה.\u0004 ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003חרדה מסלקת דמים\u0004 של נידה! ומשיבים: \u0003פחדא\u0004 \u0005[פחד]\u0006 ממושך מדבר העתיד לקרות הוא \u0003צמית\u0004 \u0005[צומת,\u0006 מקפיא את הדם ואינו יוצא\u0005],\u0006 ואילו \u0003ביעתותא מרפיא\u0004 \u0005[אימה\u0006 פתאומית \u0005מרפה\u0006 אותו\u0005]\u0006 וגורמת לשתיתתו.","שנינו במשנה שאם \u0003יש לה זכות\u0004 — \u0003היתה\u0004 תולה לה שנה, שנתיים, או שלוש. שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 \u0003לא\u0004 כדעת \u0003אבא יוסי בן חנן, ולא\u0004 כדעת \u0003ר' אלעזר בן יצחק איש כפר דרום, ולא\u0004 כדעת \u0003ר' ישמעאל.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אם יש לה זכות —\u0004 \u0003תולה לה שלשה חדשים, כדי\u0004 הזמן של \u0003הכרת העובר,\u0004 שניתן לה זמן זה כנגד הזמן של \"ונזרעה זרע\", אלו \u0003דברי אבא יוסי בן חנן. ר' אלעזר בן יצחק איש כפר דרום אומר: תשעה חדשים\u0004 הזכות תולה לה, \u0003שנאמר:\u0004 \u0003\"ונקתה ונזרעה זרע\"\u0004 (במדבר ה, כח), כלומר, \"ונקתה\" על ידי הזכות, משך זמן של \"ונזרעה זרע\", \u0003ולהלן הוא אומר \"זרע יעבדנו יספר\"\u0004 (תהלים כב, לא), כלומר, \u0003זרע הראוי לספר\u0004 (לדבר) לאחר זמן כשיגדל, ולאחר תשעה חודשי הריון נולד ילד הראוי לחיות, ובפחות מכן נפל הוא.","\u0003ר' ישמעאל אומר: שנים עשר חדש\u0004 הזכות תולה לה. \u0003ואף על פי שאין ראיה לדבר\u0004 שזכות תולה לחוטא במשך זמן זה — יש \u0003זכר\u0004 (רמז) \u0003לדבר\u0004 בכתוב, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בדברי דניאל לנבוכדנצר לאחר שפתר את חלומו לרעה: \u0003\"להן מלכא מלכי ישפר עליך וחטיך בצדקה פרק ועויתך במחן ענין\u0004 \u0005[לכן המלך מלכי, ייטב עליך\u0006 (דברי) \u0005וחטאך בצדקה פדה ועוונך בחנינת עניים]\u0006"],["\u0003הן תהוה ארכא לשלותך\"\u0004 \u0005[ואז תהיה ארכה לשלוותך]\u0006 (דניאל ד, כד), שלא יבואו עליך כל הפורענויות שראית בחלומך, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כלא מטא\u0004 \u0005[כל\u0006 הפורענות \u0005באה]\u0006 \u0003על נבוכדנצר מלכא\"\u0004 \u0005[המלך]\u0006 (דניאל ד, כה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 שהיה הדבר \u0003\"לקצת ירחין תרי עשר\"\u0004 \u0005[בסוף שנים עשר חודש]\u0006 (דניאל ד, כו). ומכאן למד שזכות תולה ודוחה את הפורענות במשך שנה אחת. ועל כל פנים משנתנו אינה כאף אחת משיטות אלה!","ומשיבים: \u0003לעולם\u0004 תפרש שמשנתנו כשיטת \u0003ר' ישמעאל,\u0004 שזכות תולה לשנה, \u0003ואשכח קרא דאמר ותני\u0004 \u0005[ומצא כתוב\u0006 נוסף \u0005שאומר ושונה]\u0006 שזכות תולה כמה פעמים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כה אמר ה' על שלשה פשעי אדום\u0004 (אסלח), ועל ארבעה לא אשיבנו","\u0003\"\u0004(עמוס א, יא) משמע ששלוש פעמים יכולה פורענות להידחות, שנה אחר שנה. ושואלים: \u0003ומאי\u0004 \u0005[ומה]\u0006 הלשון \u0003\"אף על פי שאין ראיה לדבר זכר לדבר\",\u0004 שהרי לכאורה ראיה גדולה היא שהפורענות נדחית שלוש פעמים! ומשיבים: \u0003דלמא שאני\u0004 \u0005[שמא שונים]\u0006 \u0003גוים דלא מפקיד דינא עלייהו\u0004 \u0005[שאין הדין\u0006 נזכר ו\u0005נפקד עליהם]\u0006 כל כך כמו לישראל, שה' מדקדק יותר במעשיהם וממהר להיפרע מהם, לכן אין כאן ראיה גמורה.","שנינו במשנה: \u0003ויש זכות תולה\u0004 לסוטה \u0003שלש שנים.\u0004 שואלים: \u0003זכות דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003זכות\u0004 של \u0003תורה\u0004 שלמדה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אינה מצווה ועושה היא,\u0004 שלכל הדעות אין מצוה על האשה ללמוד תורה, ואין על מעשה זה שכר מרובה כל כך! \u0003אלא\u0004 תאמר \u0003זכות\u0004 של \u0003מצוה\u0004 שעשתה, אולם","\u0003זכות\u0004 של \u0003מצוה מי מגנא כולי האי\u0004 \u0005[האם\u0006 היא \u0005מגינה כל כך]\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003את זו דרש ר' מנחם בר יוסי: \"כי נר מצוה ותורה אור\"\u0004 (משלי ו, כג), \u0003תלה הכתוב את המצוה\u0004 לדמות אותה \u0003בנר, ואת התורה באור\u0004 (השמש). \u0003את המצוה בנר —\u0004 \u0003לומר לך: מה נר אינה מגינה\u0004 על האדם על ידי האור \u0003אלא לפי שעה,\u0004 כל עוד הוא דולק בידו — \u0003אף מצוה אינה מגינה אלא לפי שעה,\u0004 כלומר, באותה שעה.","\u0003ואת התורה\u0004 תלה \u0003באור, לומר לך: מה אור מגין לעולם —\u0004 \u0003אף תורה מגינה לעולם. ואומר\u0004 על התורה: \u0003\"בהתהלכך תנחה אתך\u0004 בשכבך תשמור עליך והקיצות היא תשיחך\u0003\"\u0004 (משלי ו, כב). \u0003\"בהתהלכך תנחה אתך\" —\u0004 \u0003זה\u0004 כשאתה מתהלך חי בתוך \u0003העולם הזה. \"בשכבך תשמר עליך\"\u0004 (משלי ו, כב) — \u0003זו\u0004 זמן ה\u0003מיתה\u0004 שהאדם שוכב בקברו. \u0003\"והקיצות היא תשיחך\" —\u0004 \u0003לעתיד לבא\u0004 לאחר תחייתיקיצת המתים.","\u0003משל לאדם שהיה מהלך באישון\u0004 (בחושך) \u0003לילה ואפילה, ומתיירא מן הקוצים ומן הפחתים\u0004 (הבורות) \u0003ומן הברקנים\u0004 שאינו רואה בגלל החושך, \u0003ומחיה רעה ומן הליסטין\u0004 (השודדים) המצויים בלילה, \u0003ואינו יודע באיזה דרך\u0004 יהא \u0003מהלך.\u0004","אם \u0003נזדמנה לו אבוקה של אור\u0004 (אש) שהיא משל למצוה — \u0003ניצל מן הקוצים ומן הפחתים ומן הברקנים, ועדיין מתיירא מחיה רעה ומן הליסטין, ו\u0004עדיין \u0003אינו יודע באיזה דרך מהלך. כיון שעלה עמוד השחר\u0004 שהוא משל ללימוד התורה — \u0003ניצל מחיה רעה ומן הלסטין,\u0004 שאינם משוטטים עוד בדרכים, \u0003ועדיין אינו יודע באיזה דרך מהלך.\u0004 אם \u0003הגיע לפרשת דרכים\u0004 ומכיר את הדרך — \u0003ניצל מכולם.\u0004","\u0003דבר אחר: עבירה מכבה מצוה, ואין עבירה מכבה תורה, שנאמר:\u0004 \u0003\"מים רבים לא יוכלו לכבות את האהבה\"\u0004 (שיר השירים ח, ז). ומכל מקום, משמע מכאן שאין המצוה שעשתה קודם מגינה עליה עכשיו מן הפורענות, ואם כן כיצד תגן זכות המצוה על הסוטה?","\u0003אמר רב יוסף\u0004 כך צריך להבין את ההשוואה: \u0003מצוה, בעידנא דעסיק\u0004 \u0005[בזמן ש\u0006הוא \u0005עוסק]\u0006 \u0003בה —\u0004 \u0003מגנא\u0004 \u0005[מגינה]\u0006 היא מן הפורענות \u0003ומצלא\u0004 \u0005[ומצילה]\u0006 מיצר הרע, \u0003בעידנא דלא עסיק\u0004 \u0005[בזמן שאינו עוסק]\u0006 \u0003בה —\u0004 \u0003אגוני מגנא אצולי לא מצלא\u0004 \u0005[מגינה\u0006 היא מן הפורענות, אבל \u0005להציל אינה מצילה]\u0006 מן היצר. \u0003תורה, בין בעידנא דעסיק\u0004 \u0005[בזמן ש\u0006הוא \u0005עוסק]\u0006 \u0003בה ובין בעידנא דלא עסיק\u0004 \u0005[בזמן שאינו עוסק]\u0006 \u0003בה — הריהי\u0004 \u0003מגנא ומצלא\u0004 \u0005[מגינה\u0006 היא \u0005ומצילה],\u0006 ואם כן, גם לפי האמור בברייתא יכולה זכות המצוה שעשתה להגן עליה מפורענות.","\u0003מתקיף לה\u0004 \u0005[מקשה על\u0006 הסבר \u0005זה]\u0006 \u0003רבה: אלא מעתה, דואג ואחיתופל מי\u0004 \u0005[האם]\u0006 \u0003לא עסקי\u0004 \u0005[עסקו]\u0006 \u0003בתורה?\u0004 והרי ידוע במסורת שהיו חכמים גדולים, אם כן \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא הגינה עלייהו\u0004 \u0005[עליהם],\u0006 כלומר, הצילה אותם מלחטוא? \u0003אלא אמר רבא: תורה בעידנא דעסיק\u0004 \u0005[בזמן ש\u0006הוא \u0005עוסק]\u0006 \u0003בה — הריהי\u0004 \u0003מגנא ומצלא\u0004 \u0005[מגינה ומצילה],\u0006 \u0003בעידנא דלא עסיק\u0004 \u0005[בזמן שאינו עוסק]\u0006 \u0003בה —\u0004 \u0003אגוני מגנא אצולי לא מצלא\u0004 \u0005[להגן מגינה\u0006 מפורענות, אך \u0005להציל אינה מצילה]\u0006 מן היצר. ואילו \u0003מצוה, בין בעידנא דעסיק\u0004 \u0005[בזמן ש\u0006הוא \u0005עוסק]\u0006 \u0003בה בין בעידנא דלא עסיק\u0004 \u0005[בזמן שאינו עוסק]\u0006 \u0003בה —\u0004 \u0003אגוני מגנא אצולי לא מצלא\u0004 \u0005[להגן מגינה\u0006 מפורענות, \u0005להציל אינה מצילה\u0006 מן היצר\u0005].\u0006","\u0003רבינא אמר: לעולם\u0004 תפרש שהזכות שמועילה לסוטה היא \u0003זכות תורה, ודקאמרת\u0004 \u0005[ומה שאומר אתה]\u0006 הרי האשה \u0003אינה מצווה ועושה —\u0004 \u0003נהי דפקודי לא מפקדא\u0004 \u0005[אם אמנם שאינה מצווה],\u0006 מכל מקום \u0003באגרא דמקרין ומתניין בנייהו\u0004 \u0005[בשכר\u0006 זה \u0005ש\u0006הן גורמות \u0005לבניהן לקרוא\u0006 בתורה \u0005ולשנות\u0006 במשנה \u0003]\u0004 \u0003ונטרן להו לגברייהו\u0004 \u0005[ושומרות,\u0006 ממתינות \u0005להם לבעליהן]\u0006 \u0003עד דאתו מבי מדרשא\u0004 \u0005[שבאים מבית המדרש\u0006 מלימודם\u0005],\u0006 \u0003מי לא פלגאן בהדייהו\u0004 \u0005[האם אינן חולקות\u0006 שכר \u0005איתם]?\u0006 אם כן יכולה להיות לסוטה זכות תורה להגן עליה, שגרמה לאחרים ללמוד. וחוזרים לענין המשל שהוזכרו בו אבוקה ואור ופרשת דרכים.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 הנמשל לענין מי שכבר האיר לו השחר והגיע ל\u0003פרשת דרכים? אמר רב חסדא: זה תלמיד חכם\u0004 שמאירה לו התורה, \u0003ו\u0004כשמגיע \u0003יום מיתה\u0004 היא פרשת הדרכים, אז ברור לו לאן הוא הולך. \u0003רב נחמן בר יצחק אמר: זה תלמיד חכם, ו\u0004יש בו \u0003יראת חטא\u0004 המכוונת את תורתו לכיוון הנכון. \u0003מר זוטרא אמר: זה תלמיד חכם דסלקא ליה שמעתתא אליבא דהלכתא\u0004 \u0005[שעולה לו שמועתו,\u0006 תלמודו, \u0005לפי ההלכה]\u0006 שאז ברור לו שהלך בדרך אמת.","ועוד שנינו באותה ברייתא \u0003דבר אחר: עבירה מכבה מצוה,\u0004 שמבטלת את זכות עושה המצוה, \u0003ואין עבירה מכבה תורה. אמר רב יוסף: דרשיה\u0004 \u0005[דרש אותו]\u0006 \u0003ר' מנחם בר יוסי להאי קרא כי סיני\u0004 \u0005[לכתוב זה כמו\u0006 מהר \u0005סיני],\u0006 \u0003ואילמלא דרשוה\u0004 \u0005[היו דורשים אותו]\u0006 \u0003דואג ואחיתופל הכי\u0004 \u0005[כך]\u0006 \u0003לא רדפו בתר\u0004 \u0005[היו רודפים אחר]\u0006 \u0003דוד, דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כי אמרו אויבי לי... \u0003לאמר אלהים עזבו\u0004 רדפו ותפסוהו כי אין מציל\" (תהלים עא, י-יא) הרי שחשבו שה' עזבו.","ושואלים: \u0003מאי דרוש\u0004 \u0005[מה\u0006 איזה כתוב \u0005דרשו]\u0006 שהביא אותם לטעות? — פסוק זה: \u0003\"ולא יראה בך ערות דבר\u0004 ושב מאחריך\u0003\"\u0004 (דברים כג, טו), \u0003והן\u0004 ראו שעבר דוד עבירה של גילוי עריות (בבת שבע), ו\u0003אינן יודעין שעבירה מכבה מצוה ואין עבירה מכבה תורה.\u0004","אגב שדרשו בברייתא את המלה \"אהבה\" על התורה, שואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הפסוק \u0003\"\u0004אם יתן איש את כל הון ביתו באהבה \u0003בוז יבוזו לו\"\u0004 (שיר השירים ח, ז), שמשמע מכאן שאין לקנות את שכר התורה בכסף? \u0003אמר עולא:\u0004 להוציא מאנשים מסויימים, \u0003לא כשמעון אחי עזריה\u0004 שעזריה אחיו היה מפרנס אותו כדי שיעסוק בתורה, והתחלק עימו בשכר לימוד התורה, \u0003ולא כר' יוחנן דבי נשיאה\u0004 \u0005[של בית הנשיא]\u0006 שהם היו מפרנסים אותו על מנת שיעסוק בתורה,","\u0003אלא כהלל ושבנא. דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי אמר: הלל ושבנא אחי הוו\u0004 \u0005[אחים היו],\u0006 \u0003הלל עסק בתורה\u0004 מתוך עוני, \u0003שבנא עבד עיסקא\u0004 \u0005[עשה עסקים]\u0006 והתעשר. \u0003לסוף,\u0004 לאחר זמן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \"שבנא: \u0003תא נערוב וליפלוג\u0004 \u0005[בוא נערב ונחלק];\u0006 שאני אתן לך חצי כספי ואתה תתן לי חצי שכר תורתך! \u0003יצתה בת קול ואמרה \"אם יתן איש את כל הון ביתו\u0004 באהבה בוז יבוזו לו\u0003\"\u0004 (שיר השירים ח, ז)."],["שנינו במשנה, \u0003אומר בן עזאי: חייב אדם ללמד את\u0004 בתו תורה שתדע שהזכות תולה לה. \u0003ר' אליעזר אומר: כל המלמד את בתו תורה\u0004 — \u0003מלמדה תיפלות.\u0004 ותוהים: \u0003תיפלות סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר, וכי תיפלות הוא מלמדה? והלא תורה מלמד אותה! \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003כאילו למדה תיפלות.\u0004","\u0003אמר ר' אבהו: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' אליעזר —\u0004 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אני חכמה שכנתי ערמה\"\u0004 (משלי ח, יב), ומפרש: \u0003כיון שנכנסה חכמה באדם —\u0004 \u0003נכנסה עמו ערמומית,\u0004 וחושש ר' אליעזר שתשתמש האשה בערמומיות זו שבאה לה על ידי לימוד התורה לשם תיפלות.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים עליו, \u0003האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"אני חכמה\" מאי עבדי ליה\u0004 \u0005[מה עושים\u0006 הם \u0005בו]\u0006 כיצד מפרשים הם אותו? ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004כפי שאמר \u0003ר' יוסי בר' חנינא.\u0004 ש\u0003אמר ר' יוסי בר' חנינא: אין דברי תורה מתקיימין אלא במי שמעמיד עצמו ערום עליהן, שנאמר:\u0004 \u0003\"אני חכמה שכנתי ערמה\"\u0004 שאין חכמה שוכנת אלא במי שמוכן לתת כל אשר לו עד שנעשה עני וערום ממלבוש (\"ערמה\") בגלל התורה. וכיוצא בה \u0003אמר ר' יוחנן: אין דברי תורה מתקיימין אלא במי שמשים עצמו כמי שאינו, שנאמר:\u0004 \u0003\"והחכמה מאין תמצא\"\u0004 (איוב כח, יב).","שנינו במשנה, \u0003ר' יהושע אומר: רוצה אשה\u0004 בקב ותיפלות יותר מתשעה קבין ופרישות. שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה פירוש דבריו? ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003רוצה אשה בקב ותיפלות עמו,\u0004 ושתהיה מצויה עם בעלה, יותר \u0003מתשעת קבין ופרישות,\u0004 וכיון שהתיפלות חביבה עליה אין זה מן הראוי שתלמד תורה.","שנינו במשנה, \u0003הוא,\u0004 ר' יהושע, \u0003היה אומר: חסיד שוטה\u0004 ורשע ערום, ואשה פרושה, ומכות פרושין — הרי אלו מבלי עולם. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא]\u0006 \u0003חסיד שוטה?\u0004 ומסבירים: \u0003כגון דקא טבעה איתתא בנהרא\u0004 \u0005[שטובעת אשה בנהר]\u0006 \u0003ואמר: לאו אורח ארעא לאיסתכולי\u0004 \u0005[אין\u0006 זו \u0005דרך ארץ להסתכל]\u0006 \u0003בה\u0004 כאשר אינה לבושה \u0003ואצולה\u0004 \u0005[ולהצילה].\u0006","ועוד שואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא]\u0006 \u0003רשע ערום? אמר ר' יוחנן: זה המטעים\u0004 (מסביר) \u0003דבריו לדיין קודם שיבא בעל דין חברו,\u0004 וכיון שהדיין שומע את דבריו בשלימותם שלא בנוכחותו של בעל הדין השני, דעתו נוטה אליו, ומטה על ידי כך את הדין. \u0003ר' אבהו אומר:\u0004 כגון \u0003זה הנותן דינר לעני\u0004 כדי \u0003להשלים לו מאתים זוז,\u0004 כדי שמעתה לא יהיה זכאי לקבל צדקה יותר. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שיש לו מאתים זוז —\u0004 \u0003לא יטול לקט שכחה ופאה ומעשר עני,\u0004 שאינו עוד בגדר עני. ולעומת זאת, אם \u0003היה לו מאתים חסר דינר, אפילו\u0004 אם \u0003אלף\u0004 דינר \u0003נותנין לו כאחת —\u0004 \u0003הרי זה יטול.\u0004","\u0003ר' אסי אמר ר' יוחנן:\u0004 רשע ערום \u0003זה המשיא עצה למכור בנכסים מועטין.\u0004 שהלכה היא שאם מת אדם והניח נכסים מועטים שאינם מספיקים לפרנסת הבנות וגם להוריש לבנים, כל הנכסים עומדים לפרנסת הבנות בלבד, ואילו הבנים ניזונים מן הצדקה, אם זקוקים לכך. ועל כך נוספה הלכה ש\u0003אמר ר' אסי אמר ר' יוחנן: יתומים\u0004 (בנים) \u0003שקדמו\u0004 לפני שקיבלו הבנות אותם נכסים לפרנסתן \u0003ומכרו בנכסים מועטין —\u0004 \u0003מה שמכרו, מכרו\u0004 והכסף שלהם, ואם נותן להם אדם עצה כזו הרי זה רשע ערום, שגורם לבנות להפסיד את פרנסתן.","\u0003אביי אמר:\u0004 רשע ערום \u0003זה המשיא עצה למכור בנכסים כרבן שמעון בן גמליאל.\u0004 ומה עניינו — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר בצוואה \u0003\"נכסי לך, ואחריך,\u0004 לאחר מיתתך, יהיו הנכסים \u0003לפלוני\", וירד הראשון ומכר\u0004 או \u0003אכל —\u0004 \u0003השני מוציא מיד הלקוחות\u0004 את הנכסים שמכר, שהרי שלו הם, אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: אין לשני אלא מה ששייר ראשון\u0004 ואם מכר — הרי זה מכור, ואין לשני כלום. ומי שנותן עצה לראשון למכור (כדעת רבן שמעון בן גמליאל שמכירה זו תקפה) — הוא רשע ערום שמפסיד לשני את חלקו.","\u0003רב יוסף בר חמא אמר\u0004 בשם \u0003רב ששת:\u0004 רשע ערום \u0003זה המכריע אחרים באורחותיו.\u0004 כלומר, שמייעץ לאחרים לעשות כמוהו, ובעצם אינו אלא מתכוון להראות את צדקתו לאחרים. \u0003ר' זריקא אמר רב הונא:\u0004 רשע ערום \u0003זה המיקל\u0004 בהלכה \u0003לעצמו ומחמיר לאחרים. עולא אמר: זה\u0004"],["\u0003שקרא\u0004 מקרא \u0003ושנה\u0004 משנה \u0003ולא שימש תלמידי חכמים\u0004 ללמוד את טעמי הדברים. שדומה לו שהוא יודע, ומורה הלכה שלא כדין, ולכן רשע הוא. וערום — שמשום ששונה משנה ברבים הריהו מטעה אחרים שחושבים שהוא תלמיד חכם.","\u0003אתמר\u0004 \u0005[נאמר]\u0006 שדנו אמוראים בענין מי ש\u0003קרא ושנה ולא שימש תלמידי חכמים. ר' אלעזר אומר: הרי זה עם הארץ. ר' שמואל בר נחמני אמר: הרי זה בור. ר' ינאי אומר: הרי זה כותי.\u0004 שהוא דומה לכותים שנסמכים על הכתוב בלבד ולא על מסורת חכמים.","\u0003רב אחא בר יעקב אומר: הרי זה\u0004 דומה ל\u0003מגוש\u0004 (כומר, מכשף פרסי), על ידי שמטעה את האחרים בידיעותיו. \u0003אמר רב נחמן בר יצחק: מסתברא\u0004 \u0005[מסתבר]\u0006 \u0003כ\u0004דברי \u0003רב אחא בר יעקב, דאמרי אינשי\u0004 \u0005[ש\u0006כן \u0005אומרים אנשים],\u0006 מקובל בפי הבריות לומר פתגם זה: \u0003רטין מגושא ולא ידע מאי אמר, תני תנא ולא ידע מאי אמר\u0004 \u0005[רוטן המגוש ואינו יודע מה\u0006 הוא \u0005אומר, שונה חוזר המשניות ואינו יודע מה\u0006 הוא \u0005אומר].\u0006","כיון שהזכרנו ענין עם הארץ מביאים את מה ש \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו עם הארץ? כל שאינו קורא קריאת שמע שחרית וערבית בברכותיה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: כל שאינו מניח תפילין. בן עזאי אומר: כל שאין לו ציצית בבגדו. ר' יונתן בן יוסף אמר: כל שיש לו בנים ואינו מגדלן ללמוד תורה. אחרים אומרים: אפילו קורא ושונה ולא שימש תלמידי חכמים —\u0004 \u0003זהו עם הארץ.\u0004","\u0003קרא\u0004 מקרא \u0003ולא שנה\u0004 משנה — \u0003הרי זה בור, לא קרא ולא שנה\u0004 כלל — \u0003עליו הכתוב אומר: \"וזרעתי את בית ישראל ואת בית יהודה זרע אדם וזרע בהמה\"\u0004 (ירמיה לא, כו), כלומר, על אדם כזה אפשר לומר שהוא כבהמה.","על הנאמר \u0003\"ירא את ה' בני ומלך\u0004 \u0003עם שונים אל תתערב\"\u0004 (משלי כד, כא), \u0003אמר ר' יצחק:\u0004 הכוונה בפסוק ל\u0003אלו ששונים הלכות\u0004 ואינם מבינים את טעמיהן. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הפירוש! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שפירוש \"שונים\" — \u0003שונין בחטא, וכ\u0004דברי \u0003רב הונא.\u0004 ש\u0003אמר רב הונא: כיון שעבר אדם עבירה ושנה בה —\u0004 \u0003הותרה לו,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא לאלה מתכוון הכתוב.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003התנאים\u0004 (חוזרי המשניות) — \u0003מבלי עולם.\u0004 ותוהים: \u0003מבלי עולם סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 הרי הם עושים עבודה חשובה ומועילה! \u0003אמר רבינא:\u0004 הכוונה לאלה \u0003שמורין הלכה\u0004 למעשה \u0003מתוך משנתן\u0004 בלבד, ואינם יודעים את טעמי משניות. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אמר ר' יהושע: וכי מבלי עולם הן? והלא מיישבי עולם הן, שנאמר: \"הליכות עולם לו\"\u0004 (חבקוק ג, ו), ודרשו מכאן שהשונה הלכות זוכה לחיי עולם הבא! \u0003אלא\u0004 הכוונה היא \u0003שמורין הלכה מתוך משנתן\u0004 בלבד.","במשנה אמרנו ש \u0003אשה פרושה\u0004 היא ממבלי עולם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003בתולה צליינית\u0004 (שמתפללת הרבה) \u0003ואלמנה שובבית\u0004 שהולכת ומבקרת את שכינותיה תדיר, \u0003וקטן\u0004 ש\u0003לא\u0004 \u0003כלו לו חדשיו —\u0004 \u0003הרי אלו מבלי עולם.\u0004","ותוהים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כך הוא]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' יוחנן: למדנו יראת חטא מבתולה\u0004 אחת, \u0003ו\u0004ענין \u0003קיבול שכר מאלמנה.\u0004 ומה עניינו, \u0003יראת חטא מבתולה\u0004 — ש\u0003ר' יוחנן שמעה לההיא\u0004 \u0005[לאותה]\u0006 \u0003בתולה דנפלה אאפה וקאמרה\u0004 \u0005[שנופלת על פניה\u0006 בתפילה \u0005ואומרת]:\u0006 \u0003רבונו של עולם, בראת גן עדן ובראת גיהנם, בראת צדיקים ובראת רשעים —\u0004 \u0003יהי רצון מלפניך\u0004 ש\u0003לא\u0004 \u0003יכשלו בי בני אדם\u0004 ויגיעו על ידי לגיהנם. ור' יוחנן התפעל מדבריה אלה ואמר שאפשר ללמוד ממנה מהי יראת חטא.","\u0003קיבול שכר מאלמנה\u0004 מה עניינו — \u0003דההיא\u0004 \u0005[שאותה]\u0006 \u0003אלמנה דהואי בי כנישתא בשיבבותה\u0004 \u0005[שהיה בית כנסת בשכנותה]\u0006 ובכל זאת \u0003כל יומא הות אתיא ומצלה בי מדרשיה\u0004 \u0005[כל יום היתה באה ומתפללת\u0006 ב\u0005בית מדרשו]\u0006 של \u0003ר' יוחנן. אמר לה\u0004 ר' יוחנן: \u0003בתי,\u0004 האם \u0003לא\u0004 קיים \u0003בית הכנסת בשיבבותך\u0004 \u0005[בשכנותך]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003רבי, ולא שכר פסיעות יש לי\u0004 על שאני הולכת להתפלל במקום מרוחק? ואם כן כיצד מכנים בתולה צליינית מבלת עולם?","ומסבירים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 בענין זה שהיא ממבלי עולם כוונתו ל\u0003כגון יוחני בת רטיבי,\u0004 שהיתה מראה את עצמה כצדקת ומתפללת הרבה, ובעצם היתה עוסקת בכישוף.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"קטן\u0004 ש\u0003לא כלו לו חדשיו\"?\u0004 שבודאי אינו כמשמעו אלא רמז לדבר אחר. \u0003הכא תרגימו\u0004 \u0005[כאן\u0006 בבבל \u0005תירגמו,\u0006 הסבירו\u0005]:\u0006 \u0003זה תלמיד חכם\u0004 שהוא כקטן, נפל, שלא כלו לו חודשיו. \u0003המבעט ברבותיו,\u0004","\u0003רבי אבא אמר: זה תלמיד\u0004 ש\u0003לא הגיע\u0004 עדיין \u0003ל\u0004דרגה שיכול להורות \u0003הוראה —\u0004 \u0003ומורה\u0004 כבר. ש\u0003אמר ר' אבהו אמר רב הונא אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"כי רבים חללים הפילה ועצמים כל הרגיה\"\u0004 (משלי ז, כו) — \u0003\"כי רבים חללים הפילה\" —\u0004 \u0003זה תלמיד חכם\u0004 ש\u0003לא הגיע להוראה ומורה,\u0004 שהוא כנפל שיוצא לפני זמנו. \u0003\"ועצמים כל הרגיה\" —\u0004 \u0003זה תלמיד חכם שהגיע להוראה\u0004 (\"עצום\") \u0003ואינו מורה,\u0004 ומונע תורה מרבים."],["\u0003ועד כמה\u0004 הוא קרוי שאינו ראוי להוראה — \u0003עד\u0004 שלמד \u0003ארבעין שנין\u0004 \u0005[שנה].\u0006 ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כך הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה אורי\u0004 \u0005[הורה]\u0006 וכל ימיו לא היו אלא ארבעים שנה! ומשיבים: מדובר פה \u0003בשוין,\u0004 שאם הגיע לדרגת ידיעה שווה לזו של החכם בעיר — רשאי להורות אפילו בפחות מארבעים.","שנינו במשנה: \u0003ומכות פרושין\u0004 הם מבלי עולם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שבעה פרושין הן\u0004 שאינם פרושים אמיתיים אלא ממבלי עולם: \u0003פרוש שיכמי, פרוש נקפי, פרוש קיזאי, פרוש מדוכיא, פרוש \"מה חובתי ואעשנה\", פרוש מאהבה, פרוש מיראה.\u0004","ומסבירים: \u0003פרוש שיכמי —\u0004 \u0003זה העושה\u0004 כ\u0003מעשה\u0004 אנשי העיר \u0003שכם,\u0004 שכשם שהם נימולו שלא לשם שמים — כך הוא נוהג בפרישות מעשיו שלא לשם שמים. \u0003פרוש נקפי —\u0004 \u0003זה המנקיף\u0004 (חובל) \u0003את רגליו,\u0004 מפני שגורר אותן כדי להיראות צנוע ועניו. \u0003פרוש קיזאי —\u0004 \u0003אמר רב נחמן בר יצחק: זה המקיז דם לכתלים\u0004 מתוך שעוצם עיניו, לכאורה מתוך פרישות וצניעות, ומתוך כך מכה ראשו בכותל, וזב ממנו דם. \u0003פרוש מדוכיא —\u0004 \u0003אמר רבה בר שילא: דמשפע כי מדוכיא\u0004 \u0005[ש\u0006הולך \u0005כפוף כמו בוכנה\u0006 של עלי\u0005]\u0006.","שנינו בברייתא: \u0003פרוש \"מה חובתי ואעשנה\".\u0004 ושואלים: \u0003הא מעליותא\u0004 \u0005[זו מעלה]\u0006 \u0003היא\u0004 אם שואל אדם ורוצה לברר מה חובתו! \u0003אלא\u0004 הכוונה היא ש\u0003אמר \"מה חובתי תו\u0004 \u0005[עוד]\u0006 \u0003ואעשנה\",\u0004 כלומר, שמתוך דבריו אנשים מבינים שהוא מושלם בכל דבר, ומחפש דברים שלא קיים עדיין.","ועוד שנינו בברייתא \u0003פרוש מאהבה פרוש מיראה\u0004 שעושים מאהבת שכר המצוות או מיראת עונש העבירות. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 \u0003אביי ורבא לתנא\u0004 (לחוזר המשניות): \u0003לא תיתני\u0004 \u0005[תשנה]\u0006 בברייתא \u0003פרוש מאהבה פרוש מיראה,\u0004 למרות שאינם עושים לשם שמים ממש, שהרי \u0003אמר רב יהודה אמר רב: לעולם יעסוק אדם בתורה ובמצות אפילו\u0004 ש\u0003לא\u0004 \u0003לשמה,\u0004 אלא אף מתוך מניעים אחרים, \u0003שמתוך ש\u0004עוסק בהן \u0003לא לשמה בא\u0004 לבסוף לעשותן \u0003לשמה.\u0004","\u0003אמר רב נחמן בר יצחק: דמטמרא מטמרא ודמגליא מגליא\u0004 \u0005[הנסתר נסתר והגלוי גלוי],\u0006 \u0003בי דינא רבה ליתפרע מהני דחפו גונדי\u0004 \u0005[בית הדין הגדול,\u0006 שבשמים, \u0005ייפרע מאלה שלובשים גלימות\u0006 של פרושים\u0005]\u0006 ואינם ראויים לכך. ובאותו נושא, בו אנו עוסקים באנשים המראים עצמם כחסידים וצדיקים, מספרים: \u0003אמר לה ינאי מלכא\u0004 \u0005[המלך]\u0006 \u0003לדביתיה\u0004 \u0005[לאשתו]\u0006 לפני מיתתו: \u0003אל תתיראי מן הפרושין, ולא ממי שאינן פרושין\u0004 (הצדוקים), \u0003אלא מן הצבועין שדומין לפרושין, שמעשיהן כמעשה זמרי\u0004 בעבירה \u0003ומבקשין שכר כפנחס\u0004 שקינא לה'.","\u0003ר' שמעון אומר: אין זכות תולה במים המרים. ואם אתה אומר הזכות תולה במים המאררין\u0004 כדברי חכמים במשנה הקודמת — \u0003מדהה\u0004 \u0005[מחשיך,\u0006 מפחית\u0005]\u0006 \u0003אתה\u0004 בכך \u0003את\u0004 כוח \u0003המים\u0004 המרים \u0003בפני כל הנשים השותות\u0004 שתסמוכנה על זכותן, ולא יודו שנטמאו. ומצד אחר \u0003מוציא אתה שם רע על הטהורות ששתו, שאומרים\u0004 הבריות: \u0003טמאות הן, אלא שתלתה להן זכות.\u0004 ואילו \u0003רבי אומר: הזכות תולה במים המאררים,\u0004 שאם יש זכות לאשה שחטאה אינה מתה מיד, ואולם \u0003אינה יולדת ואינה משבחת\u0004 (נעשית בריאה ויפה יותר), \u0003אלא מתנוונה\u0004 \u0005[מתנוונת,\u0006 נעשית חולה\u0005]\u0006 \u0003והולכת, לסוף היא מתה באותה מיתה\u0004 האמורה בסוטה.","אם \u0003נטמאת מנחתה\u0004 של הסוטה \u0003עד\u0004 (לפני) ש\u0003לא קדשה\u0004 המנחה \u0003בכלי —\u0004 \u0003הרי היא ככל המנחות\u0004 שבמקדש שאירע בהן דבר כזה, \u0003ותפדה\u0004 ותצא לחולין. \u0003ואם משקדשה בכלי\u0004 נטמאה — \u0003הרי היא ככל המנחות, ותשרף. ואלו\u0004 הסוטות \u0003שמנחותיהן נשרפות\u0004 אם קדשו כבר בכלי:"],["\u0003ה\u0004מודה ו\u0003אומרת \"טמאה אני לך\", ושבאו לה עדים שהיא טמאה, והאומרת \"איני שותה\"\u0004 אף שאינה מודה שנטמאה, \u0003ושבעלה אינו רוצה להשקותה\u0004 אחר שהביא אותה למקדש וקדשה המנחה בכלי, \u0003ושבעלה בא עליה בדרך\u0004 לבית המקדש כדי להשקותה,","\u0003וכל הנשואות לכהנים —\u0004 \u0003מנחותיהן נשרפות\u0004 כמנחות כהנים. \u0003בת ישראל שנשאת לכהן —\u0004 \u0003מנחתה נשרפת, וכהנת\u0004 (בת כהן) \u0003שנשאת לישראל —\u0004 \u0003מנחתה נאכלת.\u0004","\u0003מה בין כהן לכהנת\u0004 (בת כהן) בכלל? — \u0003מנחת כהנת נאכלת\u0004 לכהנים \u0003ומנחת כהן אינה נאכלת. כהנת מתחללת\u0004 על ידי ביאה אסורה ונאסרת להינשא לכהן ולאכול בתרומה, \u0003וכהן אין מתחלל\u0004 למרות שבא על אשה האסורה לו.","\u0003כהנת מטמאה למתים,\u0004 שאין עליה איסור להיטמא, \u0003ואין כהן מטמא למתים\u0004 אלא לקרובים המותרים לו. \u0003כהן אוכל בקדשי קדשים\u0004 (כגון חטאות ואשמות) \u0003ואין כהנת אוכלת בקדשי קדשים.\u0004","ועוד \u0003מה בין איש לאשה\u0004 בדינים שונים: \u0003האיש פורע\u0004 את ראשו \u0003ופורם\u0004 את בגדיו כשהוא מצורע, \u0003ואין האשה פורעת ופורמת. האיש מדיר את בנו בנזיר,\u0004 שיכול לנדור שיהא בנו הקטן נזיר, והבן חייב לקיים זאת אפילו כשיגדל, \u0003ואין האשה מדרת\u0004 את \u0003בנה בנזיר. האיש מגלח על נזירות אביו\u0004 שאם נדר אביו נדר נזירות, והפריש כבר קרבנות כדי להקריב בסוף נזירותו ומת, יכול הבן להשתמש בקרבנות אלה כאשר גם הוא נזיר, \u0003ואין האשה מגלחת על נזירות אביה.\u0004","\u0003האיש מקדש את בתו\u0004 לאדם אחר כשהיא קטנה וקידושיה קידושין גמורים, \u0003ואין האשה מקדשת את בתה\u0004 אפילו כשהיא קטנה. \u0003האיש מוכר את בתו\u0004 הקטנה לאמה, \u0003ואין האשה מוכרת את בתה.\u0004 \u0003האיש\u0004 שנידון לסקילה \u0003נסקל ערום, ואין האשה נסקלת ערומה. האיש נתלה\u0004 לאחר שנסקל על עבירות מסויימות, \u0003ואין האשה נתלית\u0004 כלל. \u0003האיש נמכר בגנבתו\u0004 על מנת לשלם את חובו, \u0003ואין האשה נמכרת בגניבתה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל\u0004 הנשים \u0003הנשואות לכהונה מנחותיהן נשרפות. כיצד?\u0004 היתה \u0003כהנת\u0004 או \u0003לויה\u0004 או \u0003ישראלית שנשאת לכהן —\u0004 \u0003אין מנחתה נאכלת,\u0004 מדוע \u0003מפני שיש לו\u0004 לבעלה הכהן \u0003חלק בה\u0004 במנחה, ודינה איפוא כמנחת כהן שאינה נאכלת. אך גם \u0003אינה עולה כליל\u0004 לגמרי כמנחת כהן שאינה נקמצת כלל — \u0003מפני שיש\u0004 גם \u0003לה\u0004 לאשה \u0003חלק בה. אלא\u0004 כיצד עושים — קומצים ממנה, \u0003הקומץ קרב בעצמו, והשירים קריבין\u0004 גם הם על המזבח אך בפני \u0003עצמן.\u0004","ושואלים: הרי \u0003איקרי\u0004 \u0005[קרא]\u0006 \u0003כאן\u0004 את ההלכה: \u0003כל\u0004 דבר \u0003שהוא\u0004 חייב להקריב חלק \u0003ממנו לאישים\u0004 (על המזבח) — \u0003הרי הוא ב\"בל תקטירו\"\u0004 על השאר! (\"לא תקטירו\". ויקרא ב, יא), שקרבן שחייבה התורה להעלות רק חלק ממנו (קומץ, אימורים) יש איסור מיוחד שלא להקטיר ממנו כל חלק אחר. ואם כן, כיצד ניתן להקטיר את השיריים על המזבח! \u0003אמר יהודה בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' שמעון בן פזי: דמסיק להו\u0004 \u0005[שמעלה אותם]\u0006 את השיריים \u0003לשום\u0004 (לשם) \u0003עצים,\u0004 שאינו מעלה אותם כקרבן לעצמו, אלא כחומר הסקה בלבד למזבח, ו\u0003כ\u0004דעת \u0003ר' אליעזר. דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: לריח ניחוח אי\u0004 \u0005[אין]\u0006 \u0003אתה מעלה\u0004 חלקי קרבן שאסורים להיקרב, \u0003אבל אתה מעליהו\u0004 \u0005[מעלה אותם]\u0006 \u0003לשום\u0004 (לשם) \u0003עצים.\u0004","ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003ר' אליעזר דאית ליה האי סברא\u0004 \u0005[שיש לו,\u0006 שהוא מקבל \u0005סברה זו]\u0006 שאפשר להעלות חלקי קרבן כאלה למזבח לשם עצים, \u0003אלא לרבנן דלית להו האי סברא, מאי איכא למימר\u0004 \u0005[לחכמים שאין להם,\u0006 שאינם מקבלים \u0005סברה זו, מה יש לומר]?\u0006 ומשיבים: \u0003דעבדי להו\u0004 \u0005[שעושים להם]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר בר' שמעון. דתניא\u0004 \u0003[ש\u0004כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אלעזר בר' שמעון אומר\u0004 לגבי מנחת חוטא של כהנים שנקמצת: \u0003הקומץ קרב בעצמו\u0004 כקומץ של כל מנחה, \u0003והשירים\u0004 אינם נאכלים ואינם קרבים על גבי המזבח אלא \u0003מתפזרים על בית הדשן\u0004 שלמטה מן המזבח."],["\u0003ואפילו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא פליגי עליה\u0004 \u0005[חלקו עליו],\u0006 על \u0003ר' אלעזר בר' שמעון אלא במנחת חוטא של כהנים,\u0004 ש\u0003בת הקרבה היא\u0004 המנחה כולה, שלפי שיטתם אינה נקמצת. \u0003אבל בהא\u0004 \u0005[בזו],\u0006 במנחת סוטה, \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 לר' אלעזר בר' שמעון ששייריה מתפזרים על בית הדשן.","שנינו במשנה ש \u0003בת ישראל הנשואה\u0004 לכהן מנחתה נשרפת, וכהנת הנשואה לישראל מנחתה נאכלת. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שמנחת כהנת אינה נשרפת — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וכל מנחת כהן כליל תהיה לא תאכל\"\u0004 (ויקרא ו, טז), ויש לדייק: \u0003כהן ולא כהנת.\u0004 \u0003שנינו במשנה:\u0004 \u0003כהנת מתחללת\u0004 בביאת איסור, ואילו \u0003כהן אין מתחלל.\u0004 ומסבירים: \u0003מנלן\u0004 \u0005[מניין לנו]\u0006 שכן הדבר — ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 על כהן הנושא אשה האסורה לו: \u0003\"ולא יחלל זרעו בעמיו\"\u0004 (ויקרא כא, טו), ומן הדיוק למדים: \u0003זרעו מתחלל\u0004 על ידי ביאה אסורה, \u0003והוא\u0004 עצמו \u0003אינו מתחלל\u0004 על ידי כך. \u0003עוד שנינו במשנה:\u0004 \u0003כהנת מטמאה\u0004 למתים, ואילו הכהנים אינם מיטמאים למתים, פרט לקרוביהם המפורשים בכתוב. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באיסור טומאה לכהנים: \u0003\"אמר אל הכהנים בני אהרן\"\u0004 (ויקרא כא, א), לדייק: \u0003בני אהרן ולא בנות אהרן.\u0004 \u0003עוד שנינו במשנה:\u0004 \u0003כהן אוכל בקדשי קדשים\u0004 ואין כהנת אוכלת בקדשי קדשים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במנחה שהיא מקדשי הקדשים: \u0003\"כל זכר בבני אהרן יאכלנה\"\u0004 (ויקרא ו, יא). \u0003על מה ששנינו במשנה:\u0004 \u0003ומה בין איש\u0004 לאשה — שאין האשה המצורעת פורעת ופורמת כדין האיש המצורע, מביאים: \u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003נאמר בכתוב:\u0004 \u0003\"איש\u0004 צרוע הוא טמא הוא\u0003\"\u0004 (ויקרא יג, מד), \u0003אין לי אלא איש\u0004 שנוהגים בו דיני מצורע מוחלט, \u0003אשה מנין?\u0004 — \u0003כשהוא אומר\u0004 מיד אחר כך \u0003\"והצרוע אשר בו\u0004 הנגע\u0003\"\u0004 (ויקרא יג, מה), \u0003הרי כאן שנים,\u0004 שכולל בלשון זו גם איש וגם אשה, \u0003אם כן מה תלמוד לומר\u0004 בתחילה \u0003\"איש\"\u0004 דוקא — \u0003לענין שלמטה\u0004 (שאחר כך), כלומר, לדיני פריעה ופרימה ולא לטומאה, ומכאן למדים ש\u0003איש פורע\u0004 ופורם ולא האשה. \u0003שנינו במשנה:\u0004 \u0003האיש מדיר את בנו בנזיר ואין האשה מדרת\u0004 את \u0003בנה בנזיר. אמר ר' יוחנן: הלכה היא\u0004 למשה מסיני \u0003ב\u0004הלכות \u0003נזיר,\u0004 ואין לה מקור בכתוב. שנינו במשנה: \u0003האיש מגלח על נזירות אביו ואין האשה מגלחת על נזירות אביה. אמר ר' יוחנן:\u0004 גם זאת \u0003הלכה היא\u0004 למשה מסיני \u0003בנזיר.\u0004","","","","","","","עוד שנינו במשנה: \u0003האיש מקדש את בתו ואין האשה מקדשת את בתה.\u0004 ומהיכן למדים זאת — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ואמר אבי הנערה... \u0003את בתי נתתי לאיש הזה\"\u0004 (דברים כב, טז), ללמדנו שהדבר בכוחו של האב בלבד ולא של האם. שנינו במשנה: \u0003האיש מוכר את בתו\u0004 לאמה כשהיא קטנה \u0003ואין האשה מוכרת את בתה.\u0004 ומניין הדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכי ימכר איש את בתו\u0004 לאמה\u0003\"\u0004 (שמות כא, ז), ללמדנו: דווקא איש מוכר את בתו ולא אשה. עוד \u0003שנינו במשנה:\u0004 \u0003האיש נסקל\u0004 כשהוא \u0003ערום\u0004 ואין האשה נסקלת כשהיא ערומה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — נאמר \u0003\"ורגמו אתו\"\u0004 (ויקרא כד, יד). ונברר: \u0003מאי\u0004 \u0005[מה]\u0006 יש ללמוד מן המיעוט \u0003\"אותו\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אותו ולא אותה,\u0004 שאין רוגמים את האשה כלל — \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 במפורש: \u0003\"והוצאת את האיש ההוא או את האשה ההיא...\u0004 וסקלתם באבנים\u0003\"\u0004 (דברים יז, ה)! \u0003אלא\u0004 הכוונה היא: \u0003אותו\u0004 כשהוא לעצמו ערום \u0003בלא כסותו\u0004 ומכאן גם נלמד — \u0003ולא אותה בלא כסותה.\u0004 \u0003שנינו במשנה:\u0004 \u0003האיש נתלה\u0004 לאחר שנסקל \u0003ואין\u0004 האשה נתלית. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ותלית אתו על עץ\"\u0004 (דברים כא, כב), ויש כאן מיעוט: \u0003אותו ולא אותה.\u0004 \u0003עוד שנינו:\u0004 \u0003האיש נמכר בגנבתו ואין האשה נמכרת בגניבתה. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ונמכר בגנבתו\"\u0004 (שמות כב, ב), ללמד: \u0003בגניבתו ולא בגניבתה.\u0004","","","","","\u0003ארוסה\u0004 שקינא לה הארוס, \u0003ושומרת יבם\u0004 שקינא לה היבם ונסתרו — \u0003לא שותות\u0004 מי סוטה, \u0003ולא נוטלות כתובה\u0004 מן הבעל כאשר מגרשן, שהרי נאסרו לו מחמת סתירה זו, וכיון שהיה הדבר באשמתן — אינן נוטלות כתובה. וראיה שאינן שותות — \u0003שנאמר: \"אשר תשטה אשה תחת אישה\"\u0004 (במדבר ה, כט) \u0003פרט לארוסה ושומרת יבם\u0004 שאין שתיהן בגדר \"תחת אישה\", כלומר, חיה עימו כאשתו.","אם היו הנשים הסוטות אסורות לבעליהן באיסור לאו, כגון \u0003אלמנה\u0004 שנישאה \u0003לכהן גדול,\u0004 או \u0003גרושה וחלוצה\u0004 שנישאו \u0003לכהן הדיוט,\u0004 או \u0003ממזרת\u0004"],["\u0003ונתינה\u0004 מן הגבעונים האסורים לבוא בקהל, הנשואה \u0003לישראל, ובת ישראל\u0004 הנשואה \u0003לממזר ולנתין —\u0004 \u0003לא שותות ולא נוטלות כתובה\u0004 שרק המותרות להינשא לבעליהן שותות.","\u0003ואלו לא שותות ולא נוטלות כתובה: ה\u0004מודה ו\u0003אומרת \"טמאה אני\",\u0004 וכן זו \u0003שבאו לה עדים\u0004 המעידים \u0003שהיא טמאה, והאומרת \"איני שותה\"\u0004 אף שאינה מודה שנטמאה, מאחר שהיא מסרבת לעשות זאת שלא לשתות ולא משום שנפטרה מכך.","אולם, זו ש\u0003אמר בעלה \"איני משקה\", ו\u0004כן זו \u0003שבעלה בא עליה בדרך\u0004 לבית המקדש להשקותה, לאחר שקינא לה ונסתרה — \u0003נוטלות כתובה\u0004 למרות ש\u0003לא שותות,\u0004 שהרי אשמת הבעל היא שאינה שותה.","\u0003מתו בעליהן\u0004 של הנשים שנסתרו וקינאו להן בעליהן \u0003עד\u0004 ש\u0003לא שתו, בית שמאי אומרים: נוטלות כתובה ולא שותות, ובית הלל אומרים: או שותות או לא נוטלות כתובתן.\u0004","נשים האסורות לבעליהן מדברי סופרים כגון שנשא אשה \u0003מעוברת חבירו\u0004 (שמת או שגירשה חבירו), או \u0003מניקת חבירו\u0004 שאסרו חכמים לשאתה בתוך עשרים וארבעה חודש מלידת התינוק — \u0003לא שותות ולא נוטלות כתובה,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 אין כאן איסור גמור על נשים אלו, שהרי \u0003יכול הוא להפרישה\u0004 ממנו \u0003ולהחזירה\u0004 אליו \u0003לאחר זמן.\u0004","היתה הסוטה \u0003איילונית\u0004 (שאינה מסוגלת מטבעה ללדת) או \u0003זקינה,\u0004 או \u0003שאינה ראויה לילד\u0004 מטעם אחר — \u0003לא נוטלות כתובה ולא שותות,\u0004 שיש איסור לשאת אשה כזו, שהרי מבטל מצוות פריה ורביה. \u0003ר' אלעזר אומר:\u0004 אין אלה נישואי איסור, שהרי \u0003יכול הוא לישא אשה אחרת ולפרות ולרבות הימנה,\u0004 ולכן נישואין אלה כשרים הם, והן שותות כשאר הנשים.","\u0003ושאר כל הנשים —\u0004 \u0003או שותות או\u0004 אם אינן שותות \u0003לא נוטלות כתובה. אשת כהן שותה, ו\u0004אם נבדקה ונמצאה טהורה — \u0003מותרת לבעלה. אשת סריס\u0004 גם היא \u0003שותה.\u0004","ולענין החשוד על הסוטה: \u0003על ידי כל עריות מקנין,\u0004 כלומר, יכול הבעל לקנא לאשתו מכל איש, גם אם הוא אסור עליה באיסור ערוה (כגון אביה או אחיה). \u0003חוץ מן הקטן, וממי שאינו איש\u0004 כגון שחושד בה שנבעלה לבהמה, וכיוצא בזה.","\u0003ואלו שבית דין מקנין להן,\u0004 כלומר, שבית דין נעשים כשליחים לבעל לקנא לאשתו: \u0003מי שנתחרש\u0004 (נעשה חרש) \u0003בעלה, או נשתטה\u0004 (השתגע), \u0003או שהיה חבוש בבית האסורין. לא להשקותה\u0004 ממש אם נסתרה אחר קינוי בית דין \u0003אמרו\u0004 לקנא על ידי בית דין, \u0003אלא\u0004 רק \u0003לפוסלה מכתובתה.\u0004 ואילו \u0003ר' יוסי אומר: אף להשקותה\u0004 מועיל הדבר. כיצד — \u0003לכשיצא בעלה מבית האסורין —\u0004 \u0003ישקנה.\u0004","שנינו במשנה שארוסה ושומרת יבם אינן שותות. ומדייקים מכאן: \u0003מישתא\u0004 \u0005[לשתות]\u0006 \u0003הוא\u0004 ש\u0003לא שתייא\u0004 \u0005[שותה]\u0006 \u0003הא קנוי\u0004 \u0005[הרי לקנא]\u0006 \u0003מקני\u0004 \u0005[מקנא]\u0006 \u0003לה\u0004 ונאסרת עליו על ידי הקינוי והסתירה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 ומשיבים: \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 על הנאמר בתחילת פרשת סוטה \u0003\"דבר אל בני ישראל ואמרת\u0004 אליהם\u0003\"\u0004 (במדבר ה, יב) — \"ואמרת אליהם\" בא \u0003לרבות ארוסה ושומרת יבם לקינוי.\u0004","\u0003ומתניתין מני\u0004 \u0005[ומשנתנו כ\u0006שיטת \u0005מי היא] —\u0006 כשיטת \u0003ר' יונתן היא. דתניא\u0004 [\u0005ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 מה שנאמר \u0003\"תחת אישך\"\u0004 (במדבר ה, יט), הרי זה בא למעט, \u0003פרט לארוסה\u0004 שאינה חיה עתה תחת אישה, שאינה שותה. \u0003יכול שאני מוציא אף שומרת יבם —\u0004 \u0003תלמוד לומר: \"איש איש\u0004 כי תשטה אשתו\u0003\"\u0004 (במדבר ה, יב), \"איש איש\" — הוא לשון ריבוי, ומרבה שומרת יבם, אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר: \"תחת אישך\"\u0004 (במדבר ה, יט) — \u0003פרט לשומרת יבם\u0004 שעדיין לא נישאה לו ואינה שותה. ואם יעלה על דעתך לומר: \u0003אוציא שומרת יבם ולא אוציא את ארוסה —\u0004 \u0003תלמוד לומר: \"אשר תשטה אשה תחת אישה\"\u0004 (במדבר ה, כט) — \u0003פרט לארוסה.\u0004","ומסבירים את שיטותיהם; \u0003מר אלימא ליה\u0004 \u0005[חכם זה,\u0006 ר' יונתן, \u0005חזק לו,\u0006 בעיניו יותר\u0005]\u0006 הקשר עם ה\u0003ארוסה.\u0004 וטעם הדבר משום \u0003דקידושי דידיה\u0004 \u0005[שהקידושין שלו\u0006 הם\u0005],\u0006 שהוא עצמו קידש אותה, מה שאין כן ביבם שבא מכוח קידושי אחיו, \u0003ו\u0004עוד שאם זינתה אחרי הקידושין \u0003סוקלין על ידו,\u0004 שהרי הנערה המאורסה שזינתה נסקלת, ואילו שומרת יבם רק לוקה, ולכן ממעט מהמילים \"תחת אישך\" רק שומרת יבם.","\u0003ומר אלימא ליה\u0004 \u0005[וחכם זה,\u0006 ר' יאשיה, \u0005חזקה לו,\u0006 בעיניו יותר\u0005]\u0006 הקשר עם \u0003שומרת יבם,\u0004 ומדוע? ש\u0003לא מיחסרא\u0004 \u0005[מחוסרת]\u0006 אפילו \u0003מסירה לחופה,\u0004 ונעשית אשתו של היבם מיד כשבא עליה, לכן ממעט רק ארוסה.","ושואלים: \u0003ור' יונתן\u0004 הממעט גם ארוסה וגם שומרת יבם, \u0003האי\u0004 \u0005[\u0006הכתוב \u0005הזה]\u0006 \u0003\"איש איש\" מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 שהרי הוא לשון ריבוי! ומשיבים: \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 הדבר \u0003לרבות אשת חרש, ואשת שוטה, ואשת\u0004"],["\u0003שעמום\u0004 (משוגע), שבית דין מקנאים עבורם. ושואלים עוד: \u0003ור' יאשיה האי\u0004 \u0005[\u0006כתוב \u0005זה]\u0006 \u0003\"תחת אישה\"\u0004 (במדבר ה, כט) \u0003מאי עביד ליה\u0004 \u0005[מה עושה\u0006 הוא \u0005בו]?\u0006 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך\u0006 הוא \u0005אותו]\u0006 \u0003להקיש\u0004 (להשוות) \u0003איש לאשה ואשה לאיש,\u0004 כפי שיבואר להלן.","ושואלים: \u0003אלא\u0004 לשניהם, \u0003טעמא דכתיבי הני קראי\u0004 \u0005[הטעם\u0006 דווקא, \u0005שכתובים המקראות האלה]\u0006 למעט ארוסה משתיה, \u0003הא לאו הכי הוה אמינא\u0004 \u0005[הרי לולא זה הייתי אומר]\u0006 ש\u0003ארוסה שתיא\u0004 \u0005[שותה]?\u0006 \u0003והא כי אתא\u0004 \u0005[והרי כאשר בא]\u0006 \u0003ר' אחא בר חנינא מדרומא\u0004 \u0005[מן הדרום],\u0006 \u0003אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא\u0006 זו \u0005בידו],\u0006 נאמר בפרשת סוטה: \u0003\"\u0004ויתן איש בך את שכבתו \u0003מבלעדי אישך\"\u0004 (במדבר ה, כ), לומר: \u0003משקדמה שכיבת בעל לבועל, ולא שקדמה שכיבת בועל לבעל.\u0004 ואם הוא חושד בה שזנתה בהיותה ארוסה — הלא קדמה שכיבת הבועל לשכיבת הבעל!","\u0003אמר רמי בר חמא: משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 מציאות, שבה יש צורך במיעוט מיוחד בכתוב לארוסה — \u0003כגון שבא עליה\u0004 ה\u0003ארוס בבית אביה,\u0004 כלומר, לפני שנשאה. שאף שבא עליה שלא כדין, בדרך זנות — מכל מקום ביאתו קדמה.","ושואלים: \u0003דכוותה\u0004 \u0005[כיוצא בה]\u0006 אתה צריך לפרש \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003שומרת יבם\u0004 שהצרכנו בה מיעוט לדעת ר' יונתן לומר שאינה שותה — \u0003כגון שבא עליה יבם בבית חמיה\u0004 (לפני הייבום). אולם \u0003הא\u0004 \u0005[זו]\u0006 היבמה שכבר בא עליה היבם עדיין \u0003שומרת יבם קרית\u0004 \u0005[קורא אתה]\u0006 \u0003לה?\u0004 הלא \u0003אשתו מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא,\u0004 שנעשית אשתו גמורה על ידי ביאה זו, ובודאי שותה אם קינא לה, \u0003דהאמר\u0004 \u0005[שהרי אמר]\u0006 \u0003רב:\u0004 יבם הבא על יבמתו בכל דרך של ביאה, בכוונה לייבמה או שלא בכוונה לייבמה, \u0003קנה\u0004 אותה לאשה בביאה זו \u0003לכל\u0004 דבר, ואף לקנא לה ולהשקותה!","ומשיבים: ר' יונתן סבור \u0003כשמואל,\u0004 ש\u0003אמר: לא קנה\u0004 יבם בביאה שאינה כמצוותה לגמרי \u0003אלא לדברים האמורים בפרשה\u0004 שזוכה בנחלת אחיו, ויכול לפטור אשה זו בגט, אבל אין לו זכויות בה לשאר דינים שיש לאשה נשואה. ולשיטה זו בא המיעוט לומר שאף אינה נעשית כאשתו לענין השקאתה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003רב\u0004 ש\u0003אמר כר' יאשיה,\u0004 ששומרת יבם שותה, \u0003ושמואל\u0004 ש\u0003אמר כר' יונתן\u0004 שנתמעטה שומרת יבם מהשקאה, ומחלוקתם היא בעצם מחלוקת תנאים? ודוחים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רב: אנא דאמרי\u0004 \u0005[אני שאמרתי] —\u0006 \u0003אפילו ל\u0004דעת \u0003ר' יונתן\u0004 אמרתי זאת, וכך אפשר לומר: \u0003מדאיצטריך קרא למעוטה\u0004 \u0005[מתוך שהוצרך הכתוב למעט אותה],\u0006 ולומר ששומרת יבם אינה שותה — \u0003מכלל\u0004 הדברים אתה למד ש\u0003אשתו מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא\u0004 לכל ענין אחר, אלא שכאן יש מיעוט מיוחד בכתוב."],["\u0003ושמואל אמר: אנא דאמרי\u0004 \u0005[אני שאמרתי]\u0006 את דברי — \u0003אפילו לר' יאשיה.\u0004 והטעם הוא להיפך, \u0003מדאיצטריך קרא לרבוייה\u0004 \u0005[מתוך שהוצרך הכתוב לרבות אותה]\u0006 במיוחד — \u0003מכלל\u0004 הדברים אתה למד \u0003דלאו\u0004 \u0005[שאין]\u0006 \u0003אשתו היא כלל\u0004 לשאר הדברים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: אשה שהיתה \u0003עוברת על דת\u0004 יהודית, שאינה נוהגת בצניעות, שאמרו חכמים שבעלה מוציאה בלא כתובה, האם היא \u0003צריכה התראה,\u0004 שצריך בעלה להודיע לה קודם לכן שיגרשנה אם תמשיך במעשיה אלה, בכדי \u0003להפסידה כתובתה, או אינה צריכה?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אנו אומרים]:\u0006 \u0003כיון\u0004 ש\u0003עוברת על דת היא — הריהי\u0004 \u0003לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003התראה,\u0004 שהרי היא יודעת שהיא עושה דבר אסור, \u0003או דלמא תיבעי\u0004 \u0005[שמא תצטרך]\u0006 \u0003התראה, דאי הדרה\u0004 \u0005[שאם חוזרת]\u0006 \u0003בה —\u0004 \u0003תיהדר\u0004 \u0005[תחזור]\u0006 \u0003בה\u0004 על ידי התראה זו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003ארוסה ושומרת יבם לא שותות ולא נוטלות כתובה,\u0004 ומכאן דייקנו: \u0003מישתא\u0004 \u0005[לשתות]\u0006 \u0003הוא דלא שתיא\u0004 \u0005[שאינה שותה],\u0006 \u0003הא קנויי מקני\u0004 \u0005[הרי לקנא, מקנא]\u0006 הוא \u0003לה.\u0004 ונברר: \u0003למאי\u0004 \u0005[\u0006למה, \u0005לאיזה ענין]\u0006 מקנא לה אם אינה שותה? \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003להפסידה כתובתה?\u0004 משמע שצריך להתרות בה שלא תיסתר עם איש אחר, ואם לא התרה בה אינו יכול להפסידה כתובתה, למרות שבודאי עברה על דת, שנהגה שלא בצניעות ונסתרה עם האסור לה!","\u0003אמר אביי: לא,\u0004 הכוונה היא \u0003לאוסרה עליו.\u0004 שאם קינא לה ונסתרה — הרי מאז היא אסורה עליו לעולם. \u0003רב פפא אמר:\u0004 הקינוי הוא כדי \u0003להשקותה\u0004 אחר כך \u0003כשהיא נשואה,\u0004 אם נסתרה בהיותה נשואה. \u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין מקנין לארוסה\u0004 על מנת \u0003להשקותה כשהיא ארוסה, אבל מקנין לארוסה\u0004 על מנת \u0003להשקותה כשהיא נשואה.\u0004 ומכל מקום אין ללמוד ממשנתנו דבר לענין התראה לעוברת על דת יהודית.","\u0003אמר רבא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בחלק אחר במשנתנו: \u0003אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט, ממזרת ונתינה לישראל, בת ישראל לממזר ולנתין —\u0004 \u0003לא שותות ולא נוטלות כתובה.\u0004","ונדייק מכאן: \u0003מישתא\u0004 \u0005[לשתות]\u0006 \u0003הוא דלא שתיא\u0004 \u0005[שאינן שותות],\u0006 \u0003הא קנויי\u0004 \u0005[הרי לקנא]\u0006 \u0003—\u0004 \u0003מקני להו\u0004 \u0005[מקנא להן].\u0006 \u0003ולמאי\u0004 \u0005[\u0006ולמה, \u0005לאיזה ענין]\u0006 מועיל הקינוי? \u0003אי\u0004 \u0005[אם]\u0006 כדי \u0003לאוסרן עליו —\u0004 \u0003הא אסירן וקיימן\u0004 \u0005[הרי\u0006 הן \u0005אסורות ועומדות]\u0006 בין כה וכה, שהרי עובר על איסור לא תעשה כשנושא אותן, \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 כדי \u0003להפסידן כתובתן?\u0004 משמע שללא התראה זו של קינוי איננו יכול להפסידן כתובתן, אף שהן עוברות על דת כשנוהגות שלא בצניעות.","\u0003אמר רב יהודה מדיסקרתא: לא,\u0004 הכוונה היא שמקנא לה כדי \u0003לאוסרה לבועל כ\u0004שם שאסורה ל\u0003בעל. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כשם ש\u0004סוטה \u0003אסורה לבעל —\u0004 \u0003כך אסורה\u0004 להינשא \u0003לבועל.\u0004 ואם כן אין להביא מכאן ראיה לענין התראה.","\u0003אמר רב חנינא מסורא: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו \u0003ואלו שבית דין מקנין\u0004 (מקנאים) \u0003להן\u0004 במקום הבעל: \u0003מי שנתחרש בעלה, או נשתטה, או שהיה חבוש בבית האסורין. ולא להשקותה\u0004 על ידי בית דין \u0003אמרו, אלא לפוסלה מכתובתה.\u0004 והרי מפורש כאן הטעם שמקנאים לה — כדי לפוסלה מכתובתה, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003בעי\u0004 \u0005[צריכה]\u0006 אשה שנסתרה ועברה על דת יהודית \u0003התראה.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ושואלים: \u0003וכולהו\u0004 \u0005[וכולם],\u0006 שאר החכמים שעסקו בכך, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמרי מהא\u0004 \u0005[אמרו\u0006 להוכיח \u0005מזו]\u0006 שלכאורה הרי זו ראיה מפורשת הכתובה במשנה עצמה! ומשיבים: סבורים הם \u0003דלמא שאני התם דלית\u0004 \u0005[שמא שונה שם\u0006 במשנה \u0005שאין]\u0006 \u0003לה אימתא דבעל\u0004 \u0005[אימת הבעל]\u0006 \u0003כלל,\u0004 שהרי נתחרש או שחבוש בבית האסורים, ולכן צריך להתרות בה. אבל סתם אשה הנשואה לבעלה — אימת בעלה עליה, ואינה צריכה התראה מיוחדת.","ועוד שאלה בנושא דומה \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: היתה אשה \u0003עוברת על דת ורצה בעלה\u0004 בכל זאת \u0003לקיימה\u0004 ולא לגרשה, האם \u0003מקיימה או אינו מקיימה?\u0004 כלומר, האם חובה עליו לגרשה, או שרק נתנו לו חכמים רשות לגרשה. וצדדי השאלה: \u0003מי אמרינן בקפידא דבעל תלא רחמנא\u0004 \u0005[האם אומרים אנו בהקפדת הבעל תלתה תורה]\u0006 את ענין עוברת על דת, \u0003והא לא קפיד\u0004 \u0005[וזה אינו מקפיד]\u0006 ואינו חייב לגרשה. \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דקפיד\u0004 \u0005[שהקפיד] —\u0006 \u0003קפיד\u0004 \u0005[הקפיד],\u0006 כיון שהתורה מקפידה על כך — אין תולים את הדבר ברצונו של הבעל?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממשנתנו: \u0003ואלו שבית דין מקנין\u0004 (מקנאים) \u0003להן: מי שנתחרש בעלה, או נשתטה, או שהיה חבוש בבית האסורין. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003רצה בעלה לקיימה מקיימה,\u0004 וכי \u0003עבדי\u0004 \u0005[עושים]\u0006 \u0003בית דין מידי דדלמא לא ניחא ליה\u0004 \u0005[דבר ששמא לא נוח לו]\u0006 \u0003לבעל\u0004 שיעשו אותו? ושמא אם היה בר דעת היה אומר שהוא רוצה לקיימה! \u0003ומשיבים:\u0004 \u0003סתמא דמילתא\u0004 \u0005[סתמו של דבר]\u0006 \u0003כיון שעוברת על דת היא —\u0004 \u0003מינח ניחא ליה\u0004 \u0005[נוח לו]\u0006 לכל בעל שתנהג אשתו בצניעות, ולכן יכולים בית דין לפעול על סמך הנחה זו, אך אם רצה בעלה לקיימה יכול לקיימה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003בעל שמחל על קינויו,\u0004 כלומר, קינא לה ואחר כך אמר שהוא מוחל לה, האם \u0003קינויו מחול, או אינו מחול?\u0004 וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 \u0003בקינוי\u0004 ה\u0003בעל תלא רחמנא\u0004 \u0005[תלתה תורה]\u0006 \u0003ו\u0004ה\u0003בעל הא מחיל ליה\u0004 \u0005[הרי מחל את]\u0006 \u0003קינויו, או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דקני ליה מעיקרא לא מצי מחיל ליה\u0004 \u0005[שקינא לה מתחילה אינו יכול למחול לה\u0006 עוד\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו: \u0003ואלו שבית דין מקנין להן: מי שנתחרש בעלה, או נשתטה, או שהיה חבוש בבית האסורין. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003בעל שמחל על קינויו קינויו מחול, עבדינן מידי דאתי בעל מחיל ליה\u0004 \u0005[\u0006האם \u0005עושים אנו דבר ש\u0006יכול \u0005הבעל לבוא\u0006 ו\u0005למחול אותו]?\u0006 ומשיבים: \u0003סתמא דמלתא\u0004 \u0005[סתמו של דבר]\u0006 \u0003אדם מסכים על דעת בית דין,\u0004 ואין חוששים שימחול, אך אם מחל בפירוש — הרי זה מחול.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו: \u0003ומוסרין לו\u0004 לבעל המוליך את אשתו, שקינא לה ונסתרה, לבית המקדש \u0003שני תלמידי חכמים שמא יבא עליה בדרך\u0004 ואסור עליו הדבר. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003בעל שמחל על קינויו קינויו מחול —\u0004 \u0003לחליה לקינויה ולבעול\u0004 \u0005[שימחל את קינויו ויבעל]\u0006 \u0003בהיתר! \u0004","ומשיבים: אכן, כן הוא ולכך התכוונה המשנה, \u0003מאי שנא\u0004 \u0005[מה שונה\u0006 מדוע דווקא\u0005]\u0006 \u0003תלמידי חכמים\u0004 מלווים אותו — \u0003דגמירי\u0004 \u0005[ש\u0006הם \u0005מלומדים],\u0006 \u0003דאי בעי למיבעל\u0004 \u0005[שאם רוצה\u0006 הוא \u0005לבעול]\u0006 אותה, \u0003אמרי ליה: אחליה לקינוייך ובעלה\u0004 \u0005[אומרים\u0006 הם \u0005לו: מחל על קינוייך ובעל אותה\u0006 בהיתר\u0005].\u0006","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר ר' יאשיה: שלשה דברים סח לי\u0004 החכם \u0003זעירא מאנשי ירושלים: בעל שמחל על קינויו —\u0004 \u0003קינויו מחול, וזקן ממרא\u0004 שהורה בניגוד להוראת בית הדין הגדול, \u0003שרצו בית דין למחול לו —\u0004 \u0003מוחלין לו, ובן סורר ומורה שרצו אביו ואמו למחול לו\u0004 על חטאיו — \u0003מוחלין לו.\u0004","\u0003וכשבאתי אצל חבירי שבדרום\u0004 ואמרתי להם הלכות אלה, \u0003על שנים הודו לי, ועל זקן ממרא לא הודו לי,\u0004 וטעמם — ש\u0003לא\u0004 \u0003ירבו\u0004 החכמים \u0003מחלוקת בישראל. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בעל שמחל על קינויו קינויו מחול.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן].\u0006","\u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בפרטי הלכה זו \u0003רב אחא ורבינא; חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 אם מחל \u0003קודם סתירה —\u0004 קינויו \u0003מחול,\u0004 אך אם מחל \u0003לאחר סתירה —\u0004 \u0003אינו מחול. וחד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: לאחר סתירה נמי\u0004 \u0005[גם כן]\u0006 \u0003מחול.\u0004 ומעירים: \u0003ומסתברא כמאן דאמר\u0004 \u0005[ומסתבר כ\u0006דעת \u0005מי שאומר]\u0006 \u0003אינו מחול,\u0004","\u0003ממאי\u0004 \u0005[ממה]\u0006 אנחנו למדים זאת — \u0003מדקא מהדרי רבנן\u0004 \u0005[מ\u0006תוך התשובה \u0005שמשיבים חכמים]\u0006 \u0003לר' יוסי. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי אומר: בעלה נאמן עליה\u0004 על הסוטה להביאה למקדש בלא שיבוא עליה בדרך, ואינו צריך מלווים \u0003מקל וחומר; ומה נדה שהיא ב\u0004עונש \u0003כרת —\u0004 \u0003בעלה נאמן עליה\u0004 ומותר הוא להתייחד עימה, \u0003סוטה שהיא ב\u0004איסור \u0003לאו\u0004 (לא תעשה), שהוא בעונש מלקות בלבד — \u0003לא כל שכן\u0004 שיהיה נאמן שלא יבוא עליה בדרך?","\u0003אמרו לו: לא, אם אמרת בנדה —\u0004 \u0003שכן יש לה היתר\u0004 לאחר זמן, \u0003תאמר בסוטה —\u0004 \u0003שאין לה היתר,\u0004 שהרי אשה שזנתה אסורה לבעלה לעולם.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003לאחר סתירה מחול לה,\u0004 אם כן \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 את הסוטה שגם \u0003יש לה היתר, דאי בעי מחיל ליה לקינויה ובעיל\u0004 \u0005[שאם רוצה מוחל את קינויו ובועל].\u0006 \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לאחר סתירה אינו מחול\u0004 עוד, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","שנינו במשנה: \u0003מתו בעליהן עד שלא\u0004 \u0003שתו, בית שמאי\u0004 אומרים: נוטלות כתובה ולא שותות, ובית הלל אומרים שאינן נוטלות כתובה. ושואלים: \u0003במאי קמיפלגי,\u0004 \u0005[במה\u0006 באיזה עקרון \u0005נחלקו]?\u0006 מסבירים: \u0003בית שמאי סברי\u0004 \u0005[סבורים]:\u0006 \u0003שטר העומד לגבות כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ולכן כיון שיש בידה שטר כתובה, הרי כל הכסף של הכתובה כמוחזק בידה. וכיון שאין כאן אלא רק ספק אם זינתה ואיבדה כתובתה — אין בכוח הספק להוציא מידה את הכסף הנחשב כמוחזק בידה על פי השטר."],["\u0003ובית הלל סברי\u0004 \u0005[סבורים]:\u0006 \u0003שטר העומד לגבות לאו\u0004 \u0005[לא]\u0006 \u0003כגבוי דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 ולכן כסף הכתובה הוא בחזקת הבעל ויורשיו. ומשום כך אין היא יכולה להוציא מחזקתו, שהרי יש ספק אם היא זכאית לכך.","שנינו במשנה מחלוקת לגבי הנושא מעוברת חבירו, וכן שנינו לגבי איילונית עקרה וזקינה שלא שותות ולא נוטלות שלדעת תנא קמא אינן שותות ואינן נוטלות כתובתן שיש איסור לשאת אשה כזו, שהרי מבטל מצוות פריה ורביה. ואילו ר' אלעזר אומר שאין אלו נישואי איסור שהרי יכול הוא לישא בנוסף לה אשה אחרת ולפרות ולרבות הימנה ומכיון שהנישואין כשרים, הריהן שותות. \u0003אמר רב נחמן אמר רבה בר אבוה: מחלוקת\u0004 זו היא דווקא \u0003בעקרה וזקינה,\u0004 שהטעם שאינן שותות לשיטת חכמים הוא משום שאסור לו לקיימן כשלא קיים מצוות פריה ורביה, ור' אלעזר סבר שמותר לקיימן הואיל ויכול לשאת אשה אחרת, ולכן יכול להשקותן.","\u0003אבל איילונית —\u0004 \u0003דברי הכל לא שותה ולא נוטלת כתובתה, שנאמר:\u0004 \u0003\"ונקתה ונזרעה זרע\"\u0004 (במדבר ה, כח), לומר: הדברים האלה אמורים ב\u0003מי שדרכה להזריע\u0004 וללדת, \u0003יצאה זו\u0004 האיילונית \u0003שאין דרכה להזריע,\u0004 וכיון שאין הכתוב יכול להתקיים בה — אין בה דין השקאה כלל.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך: \u0003המקנא לארוסתו ולשומרת יבם שלו, אם עד\u0004 ש\u0003לא\u0004 \u0003כנסה נסתרה\u0004 — הרי זו \u0003לא שותה ולא נוטלת כתובתה.\u0004"]]};
